package template

import (
	"fmt"
	"path/filepath"
)

// The wiring vocabulary: the parameter names block templates record in
// their scaffold values and later commands (sys create/update, deploy,
// prompt suggestions) read back. They are CLI-owned convention, not
// manifest schema — a template that names its parameters otherwise simply
// gets no assembly or suggestions. One home so a vocabulary change has
// one diff, not a scavenger hunt.
const (
	KeyAppID        = "appId"
	KeyTopic        = "topic"
	KeyContract     = "contract"
	KeyPubsub       = "pubsub"
	KeyPort         = "port"
	KeyFromPort     = "fromPort"
	KeyToPort       = "toPort"
	KeyName         = "name"
	KeyOrganization = "organization"
	KeyProjectName  = "projectName"
	KeySystemClass  = "systemClass"

	// DefaultPubsub is the pub/sub component a record belongs to when it
	// predates the pubsub value being recorded.
	DefaultPubsub = "pubsub"
)

// RecordValue reads key from a scaffold record's values as a non-empty
// string. Missing, mistyped, and empty values are errors naming the
// record, so the user knows which project to fix. It is the strict
// regime: callers validating a workspace (system assembly) use it;
// callers offering suggestions use SoftValue instead.
func RecordValue(e ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// RecordValueDefault is RecordValue with a fallback for records that
// predate the value being recorded. Only a missing key falls back; a
// present but mistyped or empty value is still an error — a record that
// names the key must say something meaningful.
func RecordValueDefault(e ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return RecordValue(e, key)
}

// SoftValue reads key from a values map as a non-empty string, reporting
// false for missing, mistyped, or empty values. It is the lenient regime:
// suggestion aids and best-effort joins skip such records rather than
// failing an operation the records themselves would still allow.
func SoftValue(values map[string]any, key string) (string, bool) {
	s, ok := values[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

// Package config reads the user-level intropy configuration file — settings
// that belong to a person and a machine rather than to a project, such as
// which GitOps repository to deploy through.
//
// Project-scoped state lives elsewhere and is found by walking up from the
// working directory (.intropy/scaffold.json); this package is
// only for the single per-user file.
//
// Precedence is flag > environment > active context > top-level keys. The
// top-level keys are defaults that the active context overrides; a file with
// no contexts behaves exactly as one written before contexts existed. The
// file is optional: a missing one yields the zero Config, because a user who
// passes every setting on the command line should never be told to create a
// config file. A file that exists but cannot be parsed is an error —
// silently ignoring it would mean a typo'd key looks exactly like a setting
// that was never set.
package config

import (
	"cmp"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

const (
	// EnvGitopsRepo overrides gitopsRepo. Settings this CLI owns are
	// namespaced with INTROPY_ so they cannot collide with other tools.
	EnvGitopsRepo = "INTROPY_GITOPS_REPO"

	// EnvArgocdServer and EnvArgocdAuthToken are deliberately *not*
	// namespaced: they are the argocd CLI's own variables, and reading them
	// means an existing Argo setup works here with no extra configuration.
	// Borrowed, not ours — do not rename them.
	EnvArgocdServer    = "ARGOCD_SERVER"
	EnvArgocdAuthToken = "ARGOCD_AUTH_TOKEN"

	// EnvTemplateRepo overrides templateRepo. The value is the template
	// library as owner/repo on GitHub.
	EnvTemplateRepo = "INTROPY_TEMPLATE_REPO"

	dirName  = "intropy"
	fileName = "config.yaml"
)

// Config is the on-disk file. Fields are optional; every one of them can also
// be supplied by flag or environment variable.
type Config struct {
	// Organization names the customer or organisation the settings belong to.
	// It has no consumer in this package; commands read the resolved value.
	Organization string `yaml:"organization"`

	// GitopsRepo is the clone URL of the GitOps repository that holds the
	// deployment overlays.
	GitopsRepo string `yaml:"gitopsRepo"`

	// ArgocdServer is a fallback for repositories whose deploy.yaml does not
	// name an ArgoCD server. deploy.yaml wins when both are present, since it
	// travels with the repository the overlays live in.
	ArgocdServer string `yaml:"argocdServer"`

	// TemplateRepo is the template library to scaffold from, as owner/repo on
	// GitHub. Empty targets the official library.
	TemplateRepo string `yaml:"templateRepo"`

	// CurrentContext selects which entry of Contexts is active. It must name
	// a key of Contexts; a dangling pointer is a load error, because
	// resolving against the wrong customer is worse than refusing to run.
	CurrentContext string `yaml:"currentContext"`

	// Contexts bundles the settings that change together when the user
	// changes customer. A context overrides only the top-level keys it sets;
	// the rest fall through to the file's defaults.
	Contexts map[string]Context `yaml:"contexts"`
}

// Context is one named bundle of customer-scoped settings. Every field is
// optional; an unset field falls through to the file's top-level default.
type Context struct {
	Organization string `yaml:"organization"`
	GitopsRepo   string `yaml:"gitopsRepo"`
	ArgocdServer string `yaml:"argocdServer"`
	TemplateRepo string `yaml:"templateRepo"`
}

// Flags carries the command-line values that take precedence over everything
// else. Empty fields fall through to the environment and then the file.
type Flags struct {
	Organization string
	GitopsRepo   string
	ArgocdServer string
	TemplateRepo string
}

// Dir returns the directory holding the configuration file. It honours
// XDG_CONFIG_HOME and otherwise uses ~/.config on every platform — matching
// argocd and gh rather than os.UserConfigDir, which on macOS would resolve to
// ~/Library/Application Support and put this file somewhere no one would look
// for it.
func Dir() (string, error) {
	if base := os.Getenv("XDG_CONFIG_HOME"); base != "" {
		return filepath.Join(base, dirName), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("locate home directory: %w", err)
	}
	return filepath.Join(home, ".config", dirName), nil
}

// Path returns the full path of the configuration file, whether or not it
// exists. Use it in error messages so users know which file to create.
func Path() (string, error) {
	dir, err := Dir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, fileName), nil
}

// Load reads the configuration file. A missing file yields the zero Config
// and no error; anything else — unreadable, malformed, or carrying unknown
// keys — is an error naming the path.
func Load() (Config, error) {
	path, err := Path()
	if err != nil {
		return Config{}, err
	}
	return loadFile(path)
}

func loadFile(path string) (Config, error) {
	f, err := os.Open(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return Config{}, nil
		}
		return Config{}, fmt.Errorf("read %s: %w", path, err)
	}
	defer f.Close()

	var cfg Config
	dec := yaml.NewDecoder(f)
	// Reject unknown keys: a misspelled setting that is silently dropped is
	// indistinguishable from one that was never set, and produces a confusing
	// failure much further along.
	dec.KnownFields(true)
	if err := dec.Decode(&cfg); err != nil {
		if errors.Is(err, io.EOF) {
			// An empty file is a legitimate way to say "no settings".
			return Config{}, nil
		}
		return Config{}, fmt.Errorf("parse %s: %w", path, err)
	}
	if err := cfg.validateCurrentContext(path); err != nil {
		return Config{}, err
	}
	return cfg, nil
}

// validateCurrentContext rejects a currentContext that names no entry of
// Contexts. The check runs at load so every command reports it, not just the
// ones that happen to read a context-backed setting.
func (c Config) validateCurrentContext(path string) error {
	if c.CurrentContext == "" {
		return nil
	}
	if _, ok := c.Contexts[c.CurrentContext]; ok {
		return nil
	}
	return UnknownContextError(path, c.CurrentContext, c.Contexts)
}

// UnknownContextError builds the message shared by load-time validation and
// 'context use': one builder so the two texts cannot drift. The format
// follows the house error voice — what failed on the first line, the valid
// values on the second.
func UnknownContextError(path, name string, contexts map[string]Context) error {
	if len(contexts) == 0 {
		return fmt.Errorf("currentContext %q does not exist in %s\nno contexts configured in %s", name, path, path)
	}
	names := make([]string, 0, len(contexts))
	for n := range contexts {
		names = append(names, n)
	}
	sort.Strings(names)
	return fmt.Errorf("currentContext %q does not exist in %s\nvalid contexts: %s", name, path, strings.Join(names, ", "))
}

// Resolve layers flag values over the environment, the active context, and
// then the file's top-level defaults. The result is what the command should
// actually use.
func (c Config) Resolve(flags Flags) Config {
	ctx := c.Contexts[c.CurrentContext]
	return Config{
		// Organization has no environment variable: it travels with the
		// customer, so it lives in contexts and flags only.
		Organization: cmp.Or(flags.Organization, ctx.Organization, c.Organization),
		GitopsRepo:   cmp.Or(flags.GitopsRepo, os.Getenv(EnvGitopsRepo), ctx.GitopsRepo, c.GitopsRepo),
		ArgocdServer: cmp.Or(flags.ArgocdServer, os.Getenv(EnvArgocdServer), ctx.ArgocdServer, c.ArgocdServer),
		TemplateRepo: cmp.Or(flags.TemplateRepo, os.Getenv(EnvTemplateRepo), ctx.TemplateRepo, c.TemplateRepo),
		// The resolved config answers "what am I pointed at"; the selection
		// itself is not re-layered, so both travel through unchanged.
		CurrentContext: c.CurrentContext,
		Contexts:       c.Contexts,
	}
}

// SetCurrentContext points the file at path at the named context, changing
// nothing else. The write is a line-level text edit rather than a YAML
// round-trip because the file is the user's: comments and key order must
// survive. The file is re-parsed before editing so a write never lands on
// contents this package would refuse to read, and the replacement goes
// through a temporary file plus rename so a crash cannot leave the file
// half-written. The file must already exist and contain the named context —
// switching to a context that is not there is a caller error, not something
// to fix by creating files.
func SetCurrentContext(path, name string) error {
	raw, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("no contexts configured in %s", path)
		}
		return fmt.Errorf("read %s: %w", path, err)
	}
	cfg, err := loadFile(path)
	if err != nil {
		return err
	}
	if _, ok := cfg.Contexts[name]; !ok {
		return UnknownContextError(path, name, cfg.Contexts)
	}
	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("stat %s: %w", path, err)
	}

	edited := replaceCurrentContextLine(string(raw), name)

	tmp, err := os.CreateTemp(filepath.Dir(path), ".config-*.tmp")
	if err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)
	if _, err := tmp.WriteString(edited); err != nil {
		tmp.Close()
		return fmt.Errorf("write %s: %w", path, err)
	}
	if err := tmp.Chmod(info.Mode()); err != nil {
		tmp.Close()
		return fmt.Errorf("write %s: %w", path, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}

// currentContextLine matches a top-level currentContext mapping. The
// column-0 anchor is load-bearing: the key is only meaningful at top level,
// so an indented look-alike nested under another key must not match.
var currentContextLine = regexp.MustCompile(`(?m)^currentContext:[^\n]*`)

// replaceCurrentContextLine swaps the value of the top-level currentContext
// key, preserving any trailing comment, or appends the key when the file
// lacks one. Appending is the only always-safe anchor: inserting before the
// contexts key would detach any comment block written directly above it.
func replaceCurrentContextLine(text, name string) string {
	replacement := "currentContext: " + name
	if loc := currentContextLine.FindStringIndex(text); loc != nil {
		line := text[loc[0]:loc[1]]
		if i := strings.Index(line, "#"); i >= 0 {
			replacement += " " + strings.TrimLeft(line[i:], " \t")
		}
		return text[:loc[0]] + replacement + text[loc[1]:]
	}
	if text != "" && !strings.HasSuffix(text, "\n") {
		text += "\n"
	}
	return text + replacement + "\n"
}

// RequireGitopsRepo returns the resolved GitOps repository URL, or an error
// listing every way it can be supplied.
func (c Config) RequireGitopsRepo() (string, error) {
	if c.GitopsRepo != "" {
		return c.GitopsRepo, nil
	}
	path, err := Path()
	if err != nil {
		path = filepath.Join("~", ".config", dirName, fileName)
	}
	return "", fmt.Errorf("no GitOps repository configured; pass --gitops-repo, set %s, or add gitopsRepo to %s", EnvGitopsRepo, path)
}

// ParseTemplateRepo splits a templateRepo value into owner and repo. An empty
// value is valid and yields empty results, meaning the official library. The
// value must be exactly owner/repo: URLs and SSH remotes are rejected here
// rather than failing later as a confusing 404 from the GitHub API, and the
// library is fetched over the GitHub API, so nothing but GitHub can serve it.
func ParseTemplateRepo(s string) (owner, repo string, err error) {
	if s == "" {
		return "", "", nil
	}
	if strings.ContainsAny(s, ":@") || strings.Contains(s, "://") {
		return "", "", fmt.Errorf("template repository %q is not owner/repo — the template library is fetched from GitHub, so configure it as owner/repo (e.g. acme/intropy-templates)", s)
	}
	parts := strings.Split(s, "/")
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return "", "", fmt.Errorf("template repository %q is not owner/repo (e.g. acme/intropy-templates)", s)
	}
	return parts[0], parts[1], nil
}

package template

import (
	"sort"
)

// TopicKey identifies a pub/sub topic within a workspace: the pub/sub
// component it lives on plus the topic name. It is the key workspace facts
// dedupe on — two scaffold records naming the same key declare the two
// halves of one contract.
//
// It is the canonical "which topic" shape for the whole CLI —
// internal/system aliases it for assembly — and its JSON tags are the
// wire vocabulary `sys create --output json` already serves.
type TopicKey struct {
	Pubsub string `json:"pubsub"`
	Name   string `json:"topic"`
}

// WorkspaceFacts is the prompt-time view of what a workspace's scaffold
// records already declare: the topics in use, the contract each carries,
// and the external ports already named, plus the one organization the
// records agree on. Create flows derive parameter
// suggestions from it; it is built by callers that scan workspaces
// (internal/system) and consumed read-only by value resolution.
//
// BuildWorkspaceFacts constructs one from scaffold entries; the zero value
// is a valid empty index.
type WorkspaceFacts struct {
	// TopicKeys holds the distinct topic keys in use, sorted by
	// (Pubsub, Topic).
	TopicKeys []TopicKey

	// Ports holds the distinct external port names in use, sorted
	// lexicographically.
	Ports []string

	// organization is the single organization the workspace's block records
	// declare. Records naming different organizations demote the fact — a
	// component belongs to exactly one organization, so a workspace that
	// disagrees with itself has nothing to suggest.
	organization string

	// contracts maps a topic key to its recorded contract type. A key whose
	// records disagree on the contract is absent — a conflicted fact is no
	// fact, and callers treat absence as "no suggestion".
	contracts map[TopicKey]string
}

// Organization returns the organization the workspace's block records
// agree on, or ("", false) when no record names one or they disagree.
func (f *WorkspaceFacts) Organization() (string, bool) {
	if f == nil || f.organization == "" {
		return "", false
	}
	return f.organization, true
}

// SetOrganization seeds the organization fact when the workspace has none.
// It is the caller's channel for context the records cannot carry — the
// resolved config's customer — and it never overrides a workspace-derived
// value: specific beats ambient. Call it before the facts feed Suggest.
func (f *WorkspaceFacts) SetOrganization(org string) {
	if f != nil && f.organization == "" {
		f.organization = org
	}
}

// ContractFor returns the contract type recorded for a topic key, or
// ("", false) when the key is unknown or its records conflict.
func (f *WorkspaceFacts) ContractFor(key TopicKey) (string, bool) {
	if f == nil {
		return "", false
	}
	c, ok := f.contracts[key]
	return c, ok
}

// WorkspaceFactEntry is the slice of a scaffold record fact-building reads:
// which block the record scaffolds and the values it recorded. Keeping the
// input this narrow lets BuildWorkspaceFacts stay in this package — a
// caller-side adapter maps full scaffold records to entries, and the import
// graph never cycles back through the scanner.
type WorkspaceFactEntry struct {
	// BlockKind is the record's block kind ("extractor", "loader",
	// "transactional-integration"); entries with any other kind contribute
	// nothing.
	BlockKind string

	// Values is the record's resolved parameter values.
	Values map[string]any
}

// BuildWorkspaceFacts indexes entries into workspace facts. It is
// deliberately lenient where Assemble is strict: entries with missing or
// mistyped wiring values are skipped rather than reported, because a
// suggestion aid must never fail an operation the records themselves would
// still allow. Organization is indexed from every entry with a block kind
// — a component's organization is not wiring — under the same conflict
// rule as contracts: one value wins, several demote the fact. The one
// cross-record rule it shares with Assemble is that conflicting contracts
// on one topic key demote the contract — suggesting either side of a
// conflict would bake a guess into the new record.
func BuildWorkspaceFacts(entries []WorkspaceFactEntry) *WorkspaceFacts {
	facts := &WorkspaceFacts{contracts: map[TopicKey]string{}}
	type contractSighting struct {
		contract   string
		conflicted bool
	}
	sightings := map[TopicKey]*contractSighting{}
	seenTopic := map[TopicKey]bool{}
	seenPort := map[string]bool{}
	orgSeen := false
	orgConflicted := false

	for _, e := range entries {
		if e.BlockKind == "" {
			continue
		}
		if org, ok := SoftValue(e.Values, KeyOrganization); ok {
			switch {
			case !orgSeen:
				orgSeen = true
				facts.organization = org
			case facts.organization != org:
				orgConflicted = true
			}
		}
		switch e.BlockKind {
		case BlockKindExtractor, BlockKindLoader:
			topic, tok := SoftValue(e.Values, KeyTopic)
			contract, cok := SoftValue(e.Values, KeyContract)
			// Default on the zero result, not on key absence: a present but
			// mistyped pubsub degrades to the default, the same regime as
			// before the accessors consolidated.
			pubsub, _ := SoftValue(e.Values, KeyPubsub)
			if pubsub == "" {
				pubsub = DefaultPubsub
			}
			if tok && cok {
				key := TopicKey{Pubsub: pubsub, Name: topic}
				if !seenTopic[key] {
					seenTopic[key] = true
					facts.TopicKeys = append(facts.TopicKeys, key)
				}
				if s, seen := sightings[key]; seen {
					if s.contract != contract {
						s.conflicted = true
					}
				} else {
					sightings[key] = &contractSighting{contract: contract}
				}
			}
			if port, ok := SoftValue(e.Values, KeyPort); ok && !seenPort[port] {
				seenPort[port] = true
				facts.Ports = append(facts.Ports, port)
			}
		case BlockKindTransactional:
			for _, key := range []string{KeyFromPort, KeyToPort} {
				if port, ok := SoftValue(e.Values, key); ok && !seenPort[port] {
					seenPort[port] = true
					facts.Ports = append(facts.Ports, port)
				}
			}
		}
	}

	if orgConflicted {
		facts.organization = ""
	}
	for key, s := range sightings {
		if !s.conflicted {
			facts.contracts[key] = s.contract
		}
	}
	sort.Slice(facts.TopicKeys, func(i, j int) bool {
		if facts.TopicKeys[i].Pubsub != facts.TopicKeys[j].Pubsub {
			return facts.TopicKeys[i].Pubsub < facts.TopicKeys[j].Pubsub
		}
		return facts.TopicKeys[i].Name < facts.TopicKeys[j].Name
	})
	sort.Strings(facts.Ports)
	return facts
}

// Package registry provides a generic OCI registry client: authentication
// via the docker credential store, artifact push/pull, tag/digest
// resolution, and image-index handling. It is policy-free — callers decide
// which artifact types and layouts are acceptable.
package registry

import (
	"context"
	"fmt"
	"net"
	"net/http"

	"oras.land/oras-go/v2/registry/remote"
	"oras.land/oras-go/v2/registry/remote/auth"
	"oras.land/oras-go/v2/registry/remote/credentials"
	"oras.land/oras-go/v2/registry/remote/retry"
)

// Client speaks to OCI registries. It carries no opinion about what an
// artifact should look like — that policy lives in the packages that use
// it (internal/release, internal/source, internal/deploy).
type Client struct {
	auth      *auth.Client
	plainHTTP func(registry string) bool
}

type options struct {
	httpClient *http.Client
	userAgent  string
	credential func(ctx context.Context, registry string) (auth.Credential, error)
	plainHTTP  func(registry string) bool
}

// Option customises NewClient.
type Option func(*options)

// WithHTTPClient replaces the default retrying HTTP client.
func WithHTTPClient(c *http.Client) Option {
	return func(o *options) { o.httpClient = c }
}

// WithUserAgent sets the User-Agent header on all registry requests.
func WithUserAgent(ua string) Option {
	return func(o *options) { o.userAgent = ua }
}

// WithCredentials replaces the docker credential store as the credential
// source.
func WithCredentials(f func(ctx context.Context, registry string) (auth.Credential, error)) Option {
	return func(o *options) { o.credential = f }
}

// WithPlainHTTP replaces the default policy for which registries are spoken
// to over plain HTTP (local registries only).
func WithPlainHTTP(f func(registry string) bool) Option {
	return func(o *options) { o.plainHTTP = f }
}

// NewClient builds a Client. Without options it authenticates through the
// docker credential store, retries through the oras default HTTP client,
// and speaks plain HTTP only to localhost registries.
func NewClient(opts ...Option) (*Client, error) {
	o := options{plainHTTP: isLocalRegistry}
	for _, opt := range opts {
		opt(&o)
	}

	credential := o.credential
	if credential == nil {
		store, err := credentials.NewStoreFromDocker(credentials.StoreOptions{})
		if err != nil {
			return nil, fmt.Errorf("load docker credentials: %w", err)
		}
		credential = credentials.Credential(store)
	}

	httpClient := o.httpClient
	if httpClient == nil {
		httpClient = retry.DefaultClient
	}

	authClient := &auth.Client{
		Client:     httpClient,
		Cache:      auth.NewCache(),
		Credential: credential,
	}
	if o.userAgent != "" {
		authClient.SetUserAgent(o.userAgent)
	}

	return &Client{auth: authClient, plainHTTP: o.plainHTTP}, nil
}

func (c *Client) repository(ref Reference) (*remote.Repository, error) {
	repo, err := remote.NewRepository(ref.Registry + "/" + ref.Repository)
	if err != nil {
		return nil, fmt.Errorf("build repository client: %w", err)
	}

	repo.Client = c.auth
	repo.PlainHTTP = c.plainHTTP(ref.Registry)

	return repo, nil
}

// isLocalRegistry follows the same convention as docker and the oras CLI:
// local registries speak plain HTTP without an explicit opt-in.
func isLocalRegistry(registry string) bool {
	host := registry
	if h, _, err := net.SplitHostPort(registry); err == nil {
		host = h
	}
	return host == "localhost" || host == "127.0.0.1" || host == "::1"
}

package main

// Shared flag descriptions. A flag that appears on more than one command
// uses the constant here rather than a hand-written string, so the help
// text cannot drift between commands. See AGENTS.md.
const (
	// flagUsageNoInput is deliberately one constant for every command: a flag
	// that means "fail rather than ask" must read identically everywhere.

	// flagUsageOutput is the --output description for commands whose plain
	// output is human-readable and whose json output goes to stdout.
	flagUsageOutput = "output format (plain, json)"

	// flagUsageOutputJSONOnly is the --output description for the two
	// scaffold commands (int create, sys create), whose only format is a
	// JSON result document.
	flagUsageOutputJSONOnly = "output format: 'json' writes the result document to stdout"

	// flagUsageEnv is the --env description for deploy subcommands that
	// take a single target environment.
	flagUsageEnv = "target environment (required)"

	flagUsageDomain = "disambiguate the component by domain"
	flagUsageSystem = "disambiguate the component by system"

	// Manifest generation places a whole system rather than disambiguating one
	// component, so these flags cannot use deploy's search descriptions.
	flagUsageManifestCreateEnv = "target environment (default: every environment in deploy.yaml)"
	flagUsageManifestDomain    = "domain to place the system under (default: where it already is in the GitOps tree, else the workspace layout)"
	flagUsageManifestSystem    = "system to inspect or generate; selects the host when the workspace holds several"
	flagUsageGitopsRepo        = "GitOps repository URL (default: gitopsRepo from the active context or config, or INTROPY_GITOPS_REPO)"
	flagUsageArgocd            = "ArgoCD server address (default: argocdServer from the active context or config, ARGOCD_SERVER, or deploy.yaml)"
	flagUsageTemplateVer       = "template release tag (default: latest)"
	flagUsageNoInput           = "never prompt; fail if a required value is missing"
	flagUsageTemplateRepo      = "template library as owner/repo (default: templateRepo from the active context or config, or INTROPY_TEMPLATE_REPO)"
	flagUsageBinding           = "local port fixture as <port>=<fixture> (repeatable)"
	flagUsageGitOpsBinding     = "GitOps port binding kind as <port>=<kind> (repeatable)"
)

package system

import (
	"fmt"
	"sort"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// parseBlock reads one scaffold record's kind-specific values into the
// component's wiring. The parser owns per-record validation only; every
// cross-component check (topic contract conflicts, port uniqueness)
// stays in Assemble, gated on the component's shape.
type parseBlock func(e template.ScaffoldEntry, c *Component) error

// blockParsers is the set of block kinds Assemble accepts. Records with a
// kind absent from the registry are skipped with a warning naming the
// supported kinds. Adding a kind is a constant, a parser, and an entry here.
var blockParsers = map[string]parseBlock{
	template.BlockKindExtractor:     parseTopicBlock,
	template.BlockKindLoader:        parseTopicBlock,
	template.BlockKindTransactional: parseTransactional,
}

// supportedKinds lists the registry keys sorted, for the unsupported-kind
// warning.
func supportedKinds() []string {
	kinds := make([]string, 0, len(blockParsers))
	for k := range blockParsers {
		kinds = append(kinds, k)
	}
	sort.Strings(kinds)
	return kinds
}

// parseTopicBlock parses the wiring of a topic block (extractor, loader):
// a required topic and contract, and one optional port. A record without a
// port stays a valid component — it just gets no From/To in the generated
// wiring.
func parseTopicBlock(e template.ScaffoldEntry, c *Component) error {
	topic, err := template.RecordValue(e, template.KeyTopic)
	if err != nil {
		return err
	}
	contract, err := template.RecordValue(e, template.KeyContract)
	if err != nil {
		return fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values", err)
	}
	pubsub, err := template.RecordValueDefault(e, template.KeyPubsub, template.DefaultPubsub)
	if err != nil {
		return err
	}
	c.Topic = &TopicKey{Pubsub: pubsub, Name: topic}
	c.topicContract = contract

	// No fallback for the port: a default would describe a binding the
	// rendered code doesn't use. A missing key is reported by the caller as
	// a warning; a present one must be a non-empty string.
	if _, ok := e.Values[template.KeyPort]; ok {
		port, err := template.RecordValue(e, template.KeyPort)
		if err != nil {
			return err
		}
		c.Port = port
		c.Ports = []string{port}
	} else {
		c.missingPort = true
	}
	return nil
}

// parseTransactional parses the wiring of a transactional block: exactly
// two ports, From before To, and no topic. Both ports are required — a
// half-wired transactional block would render broken code.
func parseTransactional(e template.ScaffoldEntry, c *Component) error {
	from, err := template.RecordValue(e, template.KeyFromPort)
	if err != nil {
		return err
	}
	to, err := template.RecordValue(e, template.KeyToPort)
	if err != nil {
		return err
	}
	c.Ports = []string{from, to}
	return nil
}

package system

import "github.com/integrio-intropy/intropy-cli/internal/template"

// TopicKey identifies a topic within the system: the pub/sub component it
// lives on plus the topic name. Two scaffolds naming the same key declare
// the two halves of one contract. It aliases the canonical type in
// internal/template — there is one "which topic" concept across the CLI,
// shared by assembly and prompt-time facts.
type TopicKey = template.TopicKey

// Topic is one assembled topic: its key and the C# contract type its
// messages carry. The identifier it gets in the generated Topics class is
// derived by the template, not the CLI.
type Topic struct {
	TopicKey
	Contract string `json:"contract"`
}

// Component is one assembled system block. Its wiring is shape-driven:
// Topic is nil for kinds without one, and Ports carries the named ports in
// the kind's order (From before To for transactional blocks).
type Component struct {
	AppID string    `json:"name"` // the Add<Kind> argument in the generated system class
	Kind  string    `json:"kind"` // a key of the blockParsers registry
	Topic *TopicKey `json:"-"`    // nil for kinds without a topic
	// Port is the single port of a topic block; empty for records that
	// predate it. Kept alongside Ports so the --output-json summary stays
	// additive-only.
	Port  string   `json:"port,omitempty"`
	Ports []string `json:"ports,omitempty"` // transactional blocks: exactly [from, to]
	Path  string   `json:"path"`            // scaffold directory, for error messages

	// topicContract is the contract type of Topic, carried on the
	// component because topics dedupe across components: the model's
	// Topics list needs one contract per key, first seen wins.
	topicContract string
	// missingPort marks a topic-block record that predates the port value,
	// so Assemble can warn without failing the record.
	missingPort bool
}

// Port is one assembled port: the named edge a block reaches the outside
// world through. The declaration carries only the deployed transport shape;
// `sys create` resolves every port to a folder under the host's test/
// directory through the generated development definition. The identifier it
// gets in the generated Ports class is derived by the template, not the CLI.
type Port struct {
	Name string `json:"name"`
}

// SharedLibrary is the workspace's contract project: referenced by the
// host, never declared as a component.
type SharedLibrary struct {
	Path string // scaffold directory
	Name string // project name; also the namespace and csproj basename
}

// Model is the assembled system declaration `sys create` generates code
// from. Name, ProjectName and SystemClass are filled in around the
// template render; Assemble leaves them empty.
type Model struct {
	Name        string // kebab-case system name
	ProjectName string // template-derived PascalCase name
	SystemClass string // template-derived ISystemDefinition class name
	Components  []Component
	Topics      []Topic // sorted by (Pubsub, Name)
	Ports       []Port  // sorted by Name
	// Shared is the workspace's shared-library scaffold, nil when none
	// exists — valid for a topic-free system, and for a topic-bearing one
	// the host template scaffolds the contracts project as a dependency.
	Shared *SharedLibrary
}

package system

import (
	"errors"
	"fmt"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// ErrNoComponents is returned when the workspace scan finds no scaffold
// record `sys create` can assemble into a component.
var ErrNoComponents = errors.New("no assemblable integration scaffolds found")

// Assemble classifies workspace scaffold records into a system model:
// shared-library records become the referenced contract project, records
// with a kind in the blockParsers registry become components, and
// everything else is skipped through warnf. The returned model's
// Name/ProjectName/SystemClass are left empty — the caller fills them
// around the template render.
func Assemble(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	var (
		components []Component
		shared     []SharedLibrary
		byAppID    = map[string]string{}   // appId -> scaffold dir
		byTopic    = map[TopicKey]Topic{}  // key -> first-seen topic
		firstDir   = map[TopicKey]string{} // key -> dir that defined it
		byPort     = map[string]string{}   // port -> scaffold dir
	)

	for _, e := range entries {
		switch {
		case e.Role == template.RoleSharedLibrary:
			name, err := template.RecordValue(e, template.KeyName)
			if err != nil {
				return nil, err
			}
			shared = append(shared, SharedLibrary{Path: e.Path, Name: name})
			continue
		case e.Role == template.RoleSystemHost:
			warnf("skipping %s: an existing system host", e.Path)
			continue
		case e.BlockKind == "":
			warnf("skipping %s: scaffold record has no block kind — re-scaffold with a newer template release to include it", e.Path)
			continue
		}

		parse, ok := blockParsers[e.BlockKind]
		if !ok {
			warnf("skipping %s: unsupported block kind %q (sys create assembles %s)", e.Path, e.BlockKind, strings.Join(supportedKinds(), ", "))
			continue
		}

		appID, err := template.RecordValue(e, template.KeyAppID)
		if err != nil {
			return nil, err
		}
		c := Component{AppID: appID, Kind: e.BlockKind, Path: e.Path}
		if err := parse(e, &c); err != nil {
			return nil, err
		}
		if c.missingPort {
			warnf("%s: scaffold record has no port — re-scaffold with a newer template release to wire From/To", e.Path)
		}

		if prev, ok := byAppID[appID]; ok {
			return nil, fmt.Errorf("duplicate component name %q: declared by both %s and %s (component names must be unique in a system)", appID, prev, e.Path)
		}
		byAppID[appID] = e.Path

		for _, port := range c.Ports {
			if prev, ok := byPort[port]; ok {
				return nil, fmt.Errorf("duplicate port %q: declared by both %s and %s (each block gets its own port; rename one in the record's values)", port, prev, e.Path)
			}
			byPort[port] = e.Path
		}

		if c.Topic != nil {
			key := *c.Topic
			if seen, ok := byTopic[key]; ok {
				if seen.Contract != c.topicContract {
					return nil, fmt.Errorf("topic %q on pubsub %q has conflicting contracts: %q (%s) vs %q (%s)", key.Name, key.Pubsub, seen.Contract, firstDir[key], c.topicContract, e.Path)
				}
			} else {
				byTopic[key] = Topic{TopicKey: key, Contract: c.topicContract}
				firstDir[key] = e.Path
			}
		}

		components = append(components, c)
	}

	if len(components) == 0 {
		return nil, fmt.Errorf("%w in this directory\nScaffold integrations first ('intropy int create <kind> -n <Name> ...'), then run 'intropy sys create' from the workspace root", ErrNoComponents)
	}
	// Zero shared libraries is a valid workspace: a topic-free system never
	// references contracts, and a topic-bearing one gets them from the host
	// template's dependency. More than one is ambiguity the template cannot
	// resolve, so it stays an error regardless of the system's shape.
	if len(shared) > 1 {
		dirs := make([]string, len(shared))
		for i, s := range shared {
			dirs[i] = s.Path
		}
		return nil, fmt.Errorf("found %d shared contract projects (%s); a system host references exactly one — remove or consolidate before re-running", len(shared), strings.Join(dirs, ", "))
	}

	topics := make([]Topic, 0, len(byTopic))
	for _, t := range byTopic {
		topics = append(topics, t)
	}
	sort.Slice(topics, func(i, j int) bool {
		if topics[i].Pubsub != topics[j].Pubsub {
			return topics[i].Pubsub < topics[j].Pubsub
		}
		return topics[i].Name < topics[j].Name
	})

	ports := make([]Port, 0, len(byPort))
	for name := range byPort {
		ports = append(ports, Port{Name: name})
	}
	sort.Slice(ports, func(i, j int) bool { return ports[i].Name < ports[j].Name })

	model := &Model{Components: components, Topics: topics, Ports: ports}
	if len(shared) == 1 {
		model.Shared = &shared[0]
	}
	return model, nil
}

package system

import (
	"fmt"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// buildPayload assembles the value map passed as SetValues to the
// system-host template. The payload carries workspace facts only — topic and
// port names, component wiring, the detected contracts sibling — and the
// template derives everything that exists only inside the generated
// files: the Topics/Ports field identifiers, the joins between
// components and those fields, and the csproj ProjectReference path.
//
// The contracts sibling travels as a relative include: the template renders
// it verbatim into the host csproj's ProjectReference, and the host is
// always created as a sibling of the contracts project, so the CLI's
// workspace-relative path and the include differ only by the leading "../".
// Computing the include here keeps the templates (and the test fixtures that
// mirror them) free of host-side path arithmetic.
func buildPayload(m *Model, outputDir, kebab string) (map[string]any, error) {
	topics := make([]any, len(m.Topics))
	for i, t := range m.Topics {
		topics[i] = map[string]any{
			"pubsub":   t.Pubsub,
			"name":     t.Name,
			"contract": t.Contract,
		}
	}

	ports := make([]any, len(m.Ports))
	for i, c := range m.Ports {
		ports[i] = map[string]any{
			"name": c.Name,
		}
	}

	components := make([]any, len(m.Components))
	for i, c := range m.Components {
		components[i] = ComponentEntry(c)
	}

	payload := map[string]any{
		"name":       kebab,
		"topics":     topics,
		"ports":      ports,
		"components": components,
	}
	if m.Shared != nil {
		include, err := contractsInclude(outputDir, *m.Shared)
		if err != nil {
			return nil, err
		}
		payload["sharedContracts"] = map[string]any{
			"name":    m.Shared.Name,
			"include": include,
		}
	}
	return payload, nil
}

// ComponentEntry is one component's wiring as the system-host template
// consumes it — both in the sys create payload and in the component list
// sys update stores in the host's scaffold record.
//
// Kind is verbatim: Assemble already validated it against the parse
// registry. The wiring fields follow the component's shape, not its kind
// — a topic carries topic, one port port, two ports fromPort/toPort —
// and the template resolves each name to the field identifier it derived
// for the topic or port. The keys match the transactional scaffold
// record's: the template library's system-host reads fromPort/toPort
// (template release v0.4.0+).
func ComponentEntry(c Component) map[string]any {
	entry := map[string]any{
		template.KeyAppID: c.AppID,
		"kind":           c.Kind,
	}
	if c.Topic != nil {
		entry[template.KeyTopic] = map[string]any{
			template.KeyPubsub: c.Topic.Pubsub,
			template.KeyName:   c.Topic.Name,
		}
	}
	switch len(c.Ports) {
	case 0:
	case 1:
		entry[template.KeyPort] = c.Ports[0]
	default:
		entry[template.KeyFromPort] = c.Ports[0]
		entry[template.KeyToPort] = c.Ports[1]
	}
	return entry
}

// contractsInclude computes the ProjectReference Include path from the
// host's output directory to the shared library's csproj, slash-separated.
func contractsInclude(outputDir string, shared SharedLibrary) (string, error) {
	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		return "", err
	}
	absShared, err := filepath.Abs(shared.Path)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absOut, absShared)
	if err != nil {
		return "", fmt.Errorf("compute path from %s to shared contracts project %s: %w", outputDir, shared.Path, err)
	}
	return filepath.ToSlash(filepath.Join(rel, shared.Name+".csproj")), nil
}

package system

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// ErrNoOrphans reports an update that found nothing to add. Callers can
// match it to suppress the message; the update itself prints the empty
// state and returns nil.
var ErrNoOrphans = errors.New("no orphaned components found")

// UpdateOptions configures Update. StartDir is the invocation directory —
// the workspace root, by the command's contract — and every writer has the
// same defaults as CreateOptions.
type UpdateOptions struct {
	StartDir   string
	Force      bool
	DryRun     bool
	OutputJSON string // "-" means stdout
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Template, Owner, Repo and Version override the pin the host's
	// scaffold record carries. Zero values render with exactly what
	// sys create pinned. Source carries the fetch seams (GitHubBaseURL
	// redirects the latest-release API call in tests).
	Template string
	Owner    string
	Repo     string
	Version  string
	Source   template.SourceOptions
}

// UpdateResult is the machine-readable summary --output json writes.
// Field names are stable and additive-only.
type UpdateResult struct {
	HostDir  string                 `json:"hostDir"`
	System   string                 `json:"system"`
	Added    []string               `json:"added"`
	Kept     []string               `json:"kept,omitempty"` // declared components whose scaffold is gone
	Files    []template.FileOutcome `json:"files,omitempty"`
	DryRun   bool                   `json:"dryRun"`
	Template string                 `json:"template,omitempty"`
	Owner    string                 `json:"owner,omitempty"`
	Repo     string                 `json:"repo,omitempty"`
	Version  string                 `json:"version,omitempty"`
}

// updatePlan is the pure half of an update: the located host, the baseline
// the host record stores, the orphans a workspace scan found, and the
// merged values a re-render consumes.
type updatePlan struct {
	hostDir  string             // host project directory, as located
	hostRec  *template.Scaffold // the host's own record
	baseline map[string]any     // the record's values, preserved verbatim
	orphans  []Component        // assemblable scaffolds the record does not declare
	kept     []string           // baseline appIds with no scaffold left
}

func (o *UpdateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Update folds orphaned components — scaffolded integrations the host's
// record does not declare — into the workspace's system host. The declared
// baseline is the host record's stored values, never a re-scan, so a
// component whose scaffold disappeared stays declared. The record is
// rewritten last, after every declaration file landed, and never on a
// conflict, so a failed update retries against an honest baseline.
func Update(ctx context.Context, opts UpdateOptions) error {
	opts.applyDefaults()

	plan, err := planUpdate(opts)
	if err != nil {
		return err
	}
	if len(plan.orphans) == 0 {
		fmt.Fprintln(opts.Stderr, ErrNoOrphans.Error())
		return nil
	}
	for _, appID := range plan.kept {
		fmt.Fprintf(opts.Stderr, "note: component %s declared but no scaffold found — kept as declared\n", appID)
	}

	// The payload and the record rewrite both start from the record's own
	// values, so hand-recorded keys survive the round-trip untouched.
	merged := make(map[string]any, len(plan.baseline))
	for k, v := range plan.baseline {
		merged[k] = v
	}
	mergedComponents, err := mergedComponentEntries(plan)
	if err != nil {
		return err
	}
	merged["components"] = mergedComponents
	if err := mergeWiring(plan, merged); err != nil {
		return err
	}

	names := make([]string, len(plan.orphans))
	for i, c := range plan.orphans {
		names[i] = c.AppID
	}
	fmt.Fprintf(opts.Stderr, "updating %s: adding components %s\n", plan.hostDir, strings.Join(names, ", "))

	// The fetch resolves once against the merged payload; the baseline and
	// override payloads re-resolve against the same extracted library, so a
	// template override fetches what it renders and one download serves
	// all three resolutions.
	prep, err := template.PrepareCreate(ctx, template.CreateOptions{
		Template:   orDefault(opts.Template, plan.hostRec.Template),
		Version:    orDefault(opts.Version, plan.hostRec.Version),
		SetValues:  merged,
		NoInput:    true,
		OnManifest: requireFactsPayload,
		Stdin:      strings.NewReader(""),
		Stdout:     opts.Stdout,
		Stderr:     opts.Stderr,
		HTTP:       opts.HTTP,
		UserAgent:  opts.UserAgent,
		Owner:      orDefault(opts.Owner, plan.hostRec.Owner),
		Repo:       orDefault(opts.Repo, plan.hostRec.Repo),
		Source:     opts.Source,
	})
	if err != nil {
		return err
	}
	defer prep.Cleanup()

	// The baseline is what the host was last rendered from; the render
	// decides per file whether a difference is the update itself (safe to
	// write) or a genuine divergence (a conflict). A template override
	// invalidates the baseline, so the strict comparison applies instead —
	// but an override naming exactly what the record already pins renders
	// from the same template and keeps it. The dashboard's sync always
	// passes its held release explicitly; without the equality check every
	// dashboard-driven update would conflict on the files it must write.
	matchesPin := (opts.Template == "" || opts.Template == plan.hostRec.Template) &&
		(opts.Version == "" || opts.Version == plan.hostRec.Version) &&
		(opts.Owner == "" || opts.Owner == plan.hostRec.Owner) &&
		(opts.Repo == "" || opts.Repo == plan.hostRec.Repo)
	var baseline map[string]any
	if matchesPin {
		baseline, err = template.Resolve(prep.Manifest, nil, strings.NewReader(""), plan.baseline, nil)
		if err != nil {
			fmt.Fprintf(opts.Stderr, "note: stored values do not re-resolve against %s@%s (%v) — treating every differing file as a conflict\n", prep.Template, prep.Version, err)
		}
	}

	outcomes, err := template.RenderUpdate(prep.SkeletonRoot, plan.hostDir, prep.Values, prep.Manifest.Spec.Files, template.RenderUpdateOptions{
		Force:    opts.Force,
		DryRun:   opts.DryRun,
		Baseline: baseline,
	})
	if err != nil {
		return err
	}
	if conflicts := conflictPaths(outcomes); len(conflicts) > 0 {
		return fmt.Errorf("declaration files differ from what the update would render: %s\nreconcile them by hand, or re-run with --force to overwrite", strings.Join(conflicts, ", "))
	}

	// The record goes last: a rerun after a partial failure must recompute
	// the same orphan set, which only an un-rewritten baseline guarantees.
	if !opts.DryRun {
		updated := *plan.hostRec
		updated.Values = merged
		if err := template.WriteScaffold(plan.hostDir, updated); err != nil {
			return err
		}
		fmt.Fprintf(opts.Stderr, "updated %s: added %d component(s)\n", plan.hostDir, len(plan.orphans))
		warnTopologyDrift(ctx, opts, plan, mergedComponents)
	}

	return maybeWriteUpdateResult(opts, plan, names, outcomes, prep)
}

// planUpdate locates the workspace's single system host and computes the
// orphan diff. Nothing is written; the scan root is the host's parent so a
// sibling scaffold is always seen, and running from inside the host
// directory is a clear error rather than a silently empty scan.
func planUpdate(opts UpdateOptions) (*updatePlan, error) {
	hosts, warnings := template.ListSystemHosts(opts.StartDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	switch len(hosts) {
	case 0:
		// A scaffold record in the invocation directory itself means the
		// user is standing in a project, not above one.
		if _, root, err := template.FindScaffold(opts.StartDir); err == nil {
			return nil, fmt.Errorf("%s is a scaffolded project, not a workspace\nrun 'intropy sys update' from the workspace root — the host's parent directory", root)
		}
		return nil, errors.New("no system host found in this directory\nrun 'intropy sys create' first, or run 'intropy sys update' from the workspace root")
	case 1:
	default:
		dirs := make([]string, len(hosts))
		for i, h := range hosts {
			dirs[i] = h.Path
		}
		return nil, fmt.Errorf("found %d system hosts (%s); 'sys update' updates exactly one — run it from a workspace with a single host", len(hosts), strings.Join(dirs, ", "))
	}
	host := hosts[0]

	// Running from inside the host means the sibling scan below sees
	// nothing; refuse rather than report a phantom no-op.
	absStart, err := filepath.Abs(opts.StartDir)
	if err != nil {
		return nil, err
	}
	absHost, err := filepath.Abs(host.Path)
	if err != nil {
		return nil, err
	}
	if rel, err := filepath.Rel(absHost, absStart); err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return nil, fmt.Errorf("%s is inside the system host %s\nrun 'intropy sys update' from the workspace root — the host's parent directory", opts.StartDir, host.Path)
	}

	// The baseline is the record's stored values: components, topics and
	// ports arrive as []any of map[string]any after the JSON round-trip.
	recordPath := filepath.Join(host.Path, filepath.FromSlash(template.ScaffoldRelPath))
	rawComponents, ok := host.Values["components"].([]any)
	if !ok {
		return nil, fmt.Errorf("%s: values.components is missing or not a list — the record does not match what sys create writes", recordPath)
	}
	declared := map[string]bool{}
	for _, c := range rawComponents {
		m, ok := c.(map[string]any)
		if !ok {
			return nil, fmt.Errorf("%s: values.components entry has type %T, expected object", recordPath, c)
		}
		appID, _ := m[template.KeyAppID].(string)
		if appID == "" {
			return nil, fmt.Errorf("%s: values.components entry has no appId", recordPath)
		}
		declared[appID] = true
	}

	// Candidates come from the sibling scan; the host's parent is the
	// system root regardless of where below it the command was invoked.
	scanRoot := filepath.Dir(host.Path)
	entries, scanWarnings := template.ListScaffolds(scanRoot)
	for _, w := range scanWarnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	warnf := func(format string, args ...any) {
		fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
	}
	model, err := assembleCandidates(entries, warnf)
	if err != nil {
		return nil, err
	}

	var orphans []Component
	for _, c := range model.Components {
		if !declared[c.AppID] {
			orphans = append(orphans, c)
		}
	}
	var kept []string
	present := map[string]bool{}
	for _, c := range model.Components {
		present[c.AppID] = true
	}
	for appID := range declared {
		if !present[appID] {
			kept = append(kept, appID)
		}
	}
	sort.Strings(kept)

	return &updatePlan{
		hostDir:  host.Path,
		hostRec:  &host.Scaffold,
		baseline: host.Values,
		orphans:  orphans,
		kept:     kept,
	}, nil
}

// assembleCandidates is Assemble without the zero-component refusal: an
// update against a workspace whose only scaffolds are already declared is
// a no-op, not an error.
func assembleCandidates(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	model, err := Assemble(entries, warnf)
	if errors.Is(err, ErrNoComponents) {
		return &Model{}, nil
	}
	return model, err
}

// mergedComponentEntries appends each orphan's payload entry to the
// record's stored component list. The stored entries pass through
// untouched — that is what makes a vanished scaffold unable to remove its
// component. New entries come from ComponentEntry, the same builder the
// sys create payload uses, so the stored shape and the payload shape can
// never drift apart.
func mergedComponentEntries(plan *updatePlan) ([]any, error) {
	stored, _ := plan.baseline["components"].([]any)
	merged := make([]any, 0, len(stored)+len(plan.orphans))
	merged = append(merged, stored...)
	for _, c := range plan.orphans {
		merged = append(merged, ComponentEntry(c))
	}
	return merged, nil
}

// mergeWiring folds the orphans' topics and ports into the record's stored
// lists, deduplicating by (pubsub, name) and name respectively. A stored
// entry passes through verbatim; only genuinely new names are appended.
// Component payloads build their wiring against these lists, so an orphan
// naming a topic or port the host never declared must add it here.
func mergeWiring(plan *updatePlan, merged map[string]any) error {
	recordPath := filepath.Join(plan.hostDir, filepath.FromSlash(template.ScaffoldRelPath))

	type topicKey struct{ pubsub, name string }
	seenTopics := map[topicKey]bool{}
	storedTopics, _ := plan.baseline["topics"].([]any)
	topics := make([]any, 0, len(storedTopics))
	for _, t := range storedTopics {
		m, ok := t.(map[string]any)
		if !ok {
			return fmt.Errorf("%s: values.topics entry has type %T, expected object", recordPath, t)
		}
		pubsub, _ := m[template.KeyPubsub].(string)
		name, _ := m[template.KeyName].(string)
		seenTopics[topicKey{pubsub, name}] = true
		topics = append(topics, t)
	}

	seenPorts := map[string]bool{}
	storedPorts, _ := plan.baseline["ports"].([]any)
	ports := make([]any, 0, len(storedPorts))
	for _, p := range storedPorts {
		m, ok := p.(map[string]any)
		if !ok {
			return fmt.Errorf("%s: values.ports entry has type %T, expected object", recordPath, p)
		}
		name, _ := m[template.KeyName].(string)
		seenPorts[name] = true
		ports = append(ports, p)
	}

	// Each orphan contributes the wiring its scaffold record declared;
	// Assemble already deduplicated and cross-checked these against every
	// other scanned scaffold. The map literals are the stored shape the
	// system-host template ranges over; the key constants name the same
	// vocabulary the records carry.
	for _, c := range plan.orphans {
		if c.Topic != nil {
			key := topicKey{c.Topic.Pubsub, c.Topic.Name}
			if !seenTopics[key] {
				seenTopics[key] = true
				topics = append(topics, map[string]any{
					template.KeyPubsub:   c.Topic.Pubsub,
					template.KeyName:     c.Topic.Name,
					template.KeyContract: c.topicContract,
				})
			}
		}
		for _, p := range c.Ports {
			if !seenPorts[p] {
				seenPorts[p] = true
				ports = append(ports, map[string]any{template.KeyName: p})
			}
		}
	}

	merged["topics"] = topics
	merged["ports"] = ports
	return nil
}

// conflictPaths lists the files the update refused to overwrite.
func conflictPaths(outcomes []template.FileOutcome) []string {
	var conflicts []string
	for _, o := range outcomes {
		if o.Outcome == template.OutcomeConflict {
			conflicts = append(conflicts, o.Path)
		}
	}
	return conflicts
}

// warnTopologyDrift runs the post-update advisory check: the host's graph
// output should now name every component the update declares. Every
// failure mode — no dotnet, a broken build, a disagreeing graph — is a
// stderr warning; the update itself already succeeded.
func warnTopologyDrift(ctx context.Context, opts UpdateOptions, plan *updatePlan, mergedComponents []any) {
	t, err := topology.RunGraph(ctx, plan.hostDir)
	if err != nil {
		fmt.Fprintf(opts.Stderr, "warning: topology check skipped: %v\n", err)
		return
	}
	graphed := map[string]bool{}
	for _, c := range t.Components {
		graphed[c.Name] = true
	}
	var missing []string
	for _, c := range mergedComponents {
		m := c.(map[string]any)
		appID, _ := m[template.KeyAppID].(string)
		if !graphed[appID] {
			missing = append(missing, appID)
		}
	}
	if len(missing) > 0 {
		sort.Strings(missing)
		fmt.Fprintf(opts.Stderr, "warning: topology check: host graph does not declare %s — rebuild or check the rendered definitions\n", strings.Join(missing, ", "))
	}
}

func maybeWriteUpdateResult(opts UpdateOptions, plan *updatePlan, added []string, outcomes []template.FileOutcome, prep *template.PreparedCreate) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absHost, err := filepath.Abs(plan.hostDir)
	if err != nil {
		absHost = plan.hostDir
	}
	// System reads soft: writing the JSON result must never fail the
	// command — by the time it runs, the host record is already rewritten.
	systemName, _ := template.SoftValue(prep.Values, template.KeyName)
	result := UpdateResult{
		HostDir:  absHost,
		System:   systemName,
		Added:    added,
		Kept:     plan.kept,
		Files:    outcomes,
		DryRun:   opts.DryRun,
		Template: prep.Template,
		Owner:    prep.Owner,
		Repo:     prep.Repo,
		Version:  prep.Version,
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output: %w", err)
	}
	return nil
}

// orDefault picks the first non-empty string: an explicit flag over the
// record's pin.
func orDefault(flag, recorded string) string {
	if flag != "" {
		return flag
	}
	return recorded
}

package main

import (
	"context"
	"fmt"
	"io"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"

	"github.com/huandu/xstrings"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/system"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/spf13/cobra"
)

type createFlags struct {
	outDir          string
	output          string
	name            string
	templateVersion string
	templateRepo    string
	values          []string
	sets            []string
	force           bool
	noInput         bool
}

var intCreateFlags createFlags

var intCreateCmd = &cobra.Command{
	Use:   "create <template>",
	Short: "Create a new integration",
	Long:  "Scaffold a new integration from the official Intropy template library. The positional argument selects which template subdirectory to render (e.g. 'hello-world').",
	Args:  usageArgs(cobra.ExactArgs(1)),
	RunE: func(cmd *cobra.Command, args []string) error {
		sets, err := template.ParseSets(intCreateFlags.sets)
		if err != nil {
			return err
		}
		if intCreateFlags.output != "" && intCreateFlags.output != "json" {
			return newUsageErrorf("invalid output format %q (allowed: json)", intCreateFlags.output)
		}
		outputJSON := ""
		if intCreateFlags.output == "json" {
			outputJSON = "-"
		}
		// With no --name the output dir falls to the resolved values: a
		// template with a "name" parameter gets the kebab-cased value, the
		// same convention --name itself defaults by.
		skipOutDir := intCreateFlags.outDir == "" && intCreateFlags.name == ""
		outputDir, err := resolveCreateName(intCreateFlags.name, intCreateFlags.outDir, sets)
		if err != nil {
			return err
		}
		owner, repo, err := resolveTemplateRepo(intCreateFlags.templateRepo)
		if err != nil {
			return err
		}
		if skipOutDir {
			out, err := deriveOutDir(cmd.Context(), template.CreateOptions{
				Template:  args[0],
				Version:   intCreateFlags.templateVersion,
				SetValues: sets,
				Files:     intCreateFlags.values,
				NoInput:   intCreateFlags.noInput,
				Stdin:     cmd.InOrStdin(),
				Stdout:    cmd.OutOrStdout(),
				Stderr:    cmd.ErrOrStderr(),
				UserAgent: "intropy-cli/" + version,
				Owner:     owner,
				Repo:      repo,
			})
			if err != nil {
				return err
			}
			outputDir = out
		}
		stderr := cmd.ErrOrStderr()
		facts, warnings := system.LoadWorkspaceFacts(workspaceRootOf(outputDir))
		for _, w := range warnings {
			printWarning(stderr, w)
		}
		seedOrganization(facts)
		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()
		if err := template.Create(ctx, template.CreateOptions{
			Template:   args[0],
			OutputDir:  outputDir,
			Version:    intCreateFlags.templateVersion,
			SetValues:  sets,
			Files:      intCreateFlags.values,
			Force:      intCreateFlags.force,
			NoInput:    intCreateFlags.noInput,
			OutputJSON: outputJSON,
			Stdin:      cmd.InOrStdin(),
			Stdout:     cmd.OutOrStdout(),
			Stderr:     stderr,
			UserAgent:  "intropy-cli/" + version,
			Owner:      owner,
			Repo:       repo,
			Facts:      facts,
		}); err != nil {
			return err
		}
		return nil
	},
}

// seedOrganization feeds the resolved config's organization into the
// facts as the ambient default. A workspace whose records already agree
// on an organization keeps its own — specific beats ambient. A config
// that cannot be read contributes nothing rather than failing the
// create: a missing config file is the common case, and the prompt is
// the fallback the fact would have spared.
func seedOrganization(facts *template.WorkspaceFacts) {
	cfg, err := config.Load()
	if err != nil {
		return
	}
	facts.SetOrganization(cfg.Resolve(config.Flags{}).Organization)
}

// workspaceRootOf derives the directory whose scaffold records feed
// prompt-time suggestions: the parent of the output directory, which is
// where a flat workspace keeps the new component's siblings.
func workspaceRootOf(outputDir string) string {
	if outputDir == "" {
		return "."
	}
	return filepath.Dir(outputDir)
}

// printWarning reports a workspace-scan issue without failing the create —
// a malformed sibling record must not block scaffolding a new component.
func printWarning(stderr io.Writer, w error) {
	fmt.Fprintf(stderr, "warning: %v\n", w)
}

// resolveCreateName folds the -n shorthand into the set map and derives the
// output dir. -n is sugar for --set name=<v>; it also defaults the output
// dir to the kebab-cased name when -o is absent — the same normalization
// sys create applies, so a name and its kebab form are one component.
func resolveCreateName(name, output string, sets map[string]any) (string, error) {
	if name == "" {
		return output, nil
	}
	if _, ok := sets["name"]; ok {
		return "", newUsageErrorf("cannot combine --name with --set name= (they conflict)")
	}
	sets["name"] = name
	if output == "" {
		output = xstrings.ToKebabCase(name)
	}
	return output, nil
}

// deriveOutDir runs the create far enough to resolve values and returns
// the kebab-cased "name" value — the directory convention for runs that
// name neither --name nor --out-dir. A template with no "name" parameter
// leaves the run with nothing to derive from, the usage error --out-dir
// would have spared.
func deriveOutDir(ctx context.Context, opts template.CreateOptions) (string, error) {
	prep, err := template.PrepareCreate(ctx, opts)
	if err != nil {
		return "", err
	}
	defer prep.Cleanup()
	name, ok := prep.Values["name"].(string)
	if !ok || name == "" {
		return "", newUsageErrorf("--out-dir is required (template %q declares no 'name' parameter to derive it from)", opts.Template)
	}
	return xstrings.ToKebabCase(name), nil
}

func init() {
	f := intCreateCmd.Flags()
	f.StringVarP(&intCreateFlags.outDir, "out-dir", "o", "", "destination directory (defaults to the kebab-cased name)")
	f.StringVar(&intCreateFlags.output, "output", "", flagUsageOutputJSONOnly)
	_ = intCreateCmd.MarkFlagDirname("out-dir")
	f.StringVarP(&intCreateFlags.name, "name", "n", "", "integration name; sets the template's 'name' parameter and, unless --out-dir is set, becomes the output directory")
	f.StringVar(&intCreateFlags.templateVersion, "template-version", "", flagUsageTemplateVer)
	f.StringVar(&intCreateFlags.templateRepo, "template-repo", "", flagUsageTemplateRepo)
	f.StringArrayVarP(&intCreateFlags.values, "values", "f", nil, "values file in YAML/JSON (repeatable; use - to read one doc from stdin)")
	f.StringArrayVarP(&intCreateFlags.sets, "set", "s", nil, "set a value as key=value (repeatable)")
	f.BoolVar(&intCreateFlags.force, "force", false, "allow rendering into a non-empty output directory")
	f.BoolVar(&intCreateFlags.noInput, "no-input", false, flagUsageNoInput)
	intCmd.AddCommand(intCreateCmd)
}

package template

// Suggest computes prompt-time candidate values for a template's declared
// fields from workspace facts and the values confirmed so far this run.
// The result is keyed by parameter name; fields the convention registry
// does not know, and fields with no candidates, are absent.
//
// The registry is CLI-owned convention, not manifest schema: it mirrors
// the value names the block templates record (topic, pubsub, contract —
// the same names internal/system's block parsers assemble from — plus
// organization, which the records carry without assembling). A template
// whose parameters use other names simply gets no suggestions.
//
// Ports are deliberately absent: every block needs its own port (system
// assembly rejects a shared one), so an already-taken port name is an
// anti-suggestion — offering it would steer scaffolds toward a collision.
//
// Suggestions are prompt metadata only. They never enter the values map on
// their own: a candidate becomes a value only when the prompter confirms
// it with the user, and callers record the confirmed value under the
// field's name — never the candidate list.
func Suggest(fields []FieldSpec, facts *WorkspaceFacts, confirmed map[string]any) map[string][]string {
	if facts == nil {
		return nil
	}
	out := map[string][]string{}
	for _, f := range fields {
		candidates := suggestField(f, facts, confirmed)
		candidates = dropDefaultCandidate(candidates, f)
		if len(candidates) > 0 {
			out[f.Name] = candidates
		}
	}
	return out
}

// suggestField is the convention registry: parameter name -> candidates
// derivable from the facts and the values confirmed so far. Chained
// derivation (contract follows the confirmed topic) re-reads the confirmed
// values on every call rather than threading field-to-field wiring, so the
// registry stays a flat name-to-rule table.
func suggestField(f FieldSpec, facts *WorkspaceFacts, confirmed map[string]any) []string {
	switch f.Name {
	case KeyOrganization:
		// One organization or none: a component belongs to exactly one, so
		// a conflicted workspace suggests nothing rather than listing
		// candidates that cannot all be right.
		if org, ok := facts.Organization(); ok {
			return []string{org}
		}
		return nil
	case KeyTopic:
		topics := make([]string, 0, len(facts.TopicKeys))
		for _, key := range facts.TopicKeys {
			topics = append(topics, key.Name)
		}
		return topics
	case KeyPubsub:
		seen := map[string]bool{}
		var pubs []string
		for _, key := range facts.TopicKeys {
			if !seen[key.Pubsub] {
				seen[key.Pubsub] = true
				pubs = append(pubs, key.Pubsub)
			}
		}
		return pubs
	case KeyContract:
		// With a confirmed topic, the contract is constrained to it; a
		// conflicted or unknown key yields nothing rather than a guess.
		// Without one, every known contract is a candidate.
		if topic, ok := confirmedString(confirmed, KeyTopic); ok {
			pubsub, _ := confirmedString(confirmed, KeyPubsub)
			if pubsub == "" {
				pubsub = DefaultPubsub
			}
			if contract, ok := facts.ContractFor(TopicKey{Pubsub: pubsub, Name: topic}); ok {
				return []string{contract}
			}
			return nil
		}
		return knownContracts(facts)
	}
	return nil
}

// knownContracts lists every unconflicted contract the facts carry, in
// topic-key order with duplicates removed.
func knownContracts(facts *WorkspaceFacts) []string {
	seen := map[string]bool{}
	var out []string
	for _, key := range facts.TopicKeys {
		contract, ok := facts.ContractFor(key)
		if ok && !seen[contract] {
			seen[contract] = true
			out = append(out, contract)
		}
	}
	return out
}

// dropDefaultCandidate removes candidates the field's schema default
// already communicates — the prompt's default bracket and a suggestion
// list must never compete for the same value.
func dropDefaultCandidate(candidates []string, f FieldSpec) []string {
	def, ok := f.Default.(string)
	if !ok || def == "" {
		return candidates
	}
	out := candidates[:0]
	for _, c := range candidates {
		if c != def {
			out = append(out, c)
		}
	}
	return out
}

// confirmedString reads a confirmed value as a non-empty string. Confirmed
// values arrive from --set/--values/prompts and are already schema-coerced
// for declared fields; unknown or mistyped entries are treated as absent.
func confirmedString(confirmed map[string]any, key string) (string, bool) {
	s, ok := confirmed[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

package template

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

type CreateOptions struct {
	Template   string // required; subdirectory in the templates repo holding template.yaml + skeleton/
	OutputDir  string
	Version    string
	SetValues  map[string]any
	Files      []string
	Force      bool
	NoInput    bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdin      io.Reader
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library. Zero values target the
	// official library at integrio-intropy/intropy-templates; the CLI sets
	// them from --template-repo, INTROPY_TEMPLATE_REPO, or templateRepo in
	// the config file.
	Owner string
	Repo  string

	// Source carries the fetch seams shared by every template-fetch path.
	// GitHubBaseURL redirects the latest-release API call in tests.
	Source SourceOptions

	// OnManifest, when set, runs after the manifest loads and before
	// values resolve, render, dependency processing, or the scaffold
	// record write. A non-nil error aborts the create. Callers use it for
	// gates that must run before any output is written.
	OnManifest func(*Template) error

	// Facts, when set, feeds prompt-time parameter suggestions: what the
	// workspace's scaffold records already declare (topics, contracts,
	// ports). Facts propose to the prompter; they never resolve a value on
	// their own, and a nil index resolves exactly as before.
	Facts *WorkspaceFacts
}

// CreateResult is the machine-readable summary written when --output-json is
// set. It is the contract chained scaffolder steps consume; field names are
// stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`

	// Dependencies reports what happened to each spec.dependencies entry
	// (including transitive ones): rendered now ("created") or already
	// present ("exists").
	Dependencies []DependencyResult `json:"dependencies,omitempty"`
}

func (o *CreateOptions) applyDefaults() {
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
}

// sourceOpts projects the create options onto the shared fetch options. A
// Source that names its own Owner/Repo wins — it is the test seam.
func (o CreateOptions) sourceOpts() SourceOptions {
	s := o.Source
	s.Version = o.Version
	s.Stderr = o.Stderr
	s.UserAgent = o.UserAgent
	if s.Owner == "" && s.Repo == "" {
		s.Owner, s.Repo = libraryIdentity(o.Owner, o.Repo)
	}
	return s
}

// Create runs the full scaffold: resolve release, ensure the cached checkout,
// load manifest, resolve values (with optional interactive prompting), render.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if err := validateCreateOptions(opts); err != nil {
		return err
	}

	src, err := FetchSource(ctx, opts.sourceOpts())
	if err != nil {
		return err
	}
	tag := src.Version

	templateRoot, err := templateDir(src, src.Owner, src.Repo, opts.Template)
	if err != nil {
		return err
	}

	tmpl, values, err := prepareCreateTemplate(templateRoot, opts)
	if err != nil {
		return err
	}

	if err := renderCreateOutput(filepath.Join(templateRoot, templateSkeletonDir), tmpl, opts.Template, opts.OutputDir, opts.Force, values); err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (template %s)\n", opts.OutputDir, src.Owner, src.Repo, tag, opts.Template)

	// Dependencies come from the same library checkout, so they are always
	// version-locked to the component that declared them.
	depRecords, depResults, err := processDependencies(tmpl, values, opts.OutputDir, &depContext{
		repoRoot: filepath.Dir(templateRoot),
		owner:    src.Owner,
		repo:     src.Repo,
		version:  tag,
		stderr:   opts.Stderr,
		visited:  map[string]bool{},
	}, 0)
	if err != nil {
		return err
	}

	// The template field is the repo directory name (opts.Template), not
	// tmpl.Metadata.Name — it is what a later re-fetch needs.
	if err := WriteScaffold(opts.OutputDir, Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      opts.Template,
		Owner:         src.Owner,
		Repo:          src.Repo,
		Version:       tag,
		Values:        values,
		Role:          roleFromLabels(tmpl.Metadata.Labels),
		BlockKind:     blockKindFromLabels(tmpl.Metadata.Labels),
		DataFlow:      dataFlowFromLabels(tmpl.Metadata.Labels),
		DependsOn:     depRecords,
	}); err != nil {
		return err
	}

	return maybeWriteCreateResult(opts, tmpl, values, src, depResults)
}

func validateCreateOptions(opts CreateOptions) error {
	if err := validateTemplateName(opts.Template); err != nil {
		return err
	}
	if opts.OutputDir == "" {
		return errors.New("--out-dir is required")
	}
	return nil
}

func prepareCreateTemplate(templateRoot string, opts CreateOptions) (*Template, map[string]any, error) {
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, nil, err
	}
	if opts.OnManifest != nil {
		if err := opts.OnManifest(tmpl); err != nil {
			return nil, nil, err
		}
	}

	prompter := selectPrompter(&opts)
	values, err := ResolveWith(tmpl, ResolveOptions{
		Facts:    opts.Facts,
		Files:    opts.Files,
		Stdin:    opts.Stdin,
		Sets:     opts.SetValues,
		Prompter: prompter,
		Notes:    opts.Stderr,
	})
	if err != nil {
		return nil, nil, err
	}
	return tmpl, values, nil
}

// renderCreateOutput renders an extracted skeleton into outputDir, honoring
// the manifest's spec.files rules. The caller passes the skeleton root
// itself (PrepareCreate has already verified it), so the missing-skeleton
// check lives next to the fetch that could produce it.
func renderCreateOutput(skelRoot string, tmpl *Template, templateName, outputDir string, force bool, values map[string]any) error {
	if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
		return fmt.Errorf("template %q is missing %s/ directory", templateName, templateSkeletonDir)
	}
	if err := ensureOutputDir(outputDir, force); err != nil {
		return err
	}
	return RenderFiltered(skelRoot, outputDir, values, tmpl.Spec.Files)
}

func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, src *Source, deps []DependencyResult) error {
	if opts.OutputJSON == "" {
		return nil
	}

	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:     tmpl.Metadata.Name,
		Owner:        src.Owner,
		Repo:         src.Repo,
		Version:      src.Version,
		OutputDir:    absOut,
		Values:       values,
		Dependencies: deps,
	}
	if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
	data, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	if path == "-" {
		_, err := stdout.Write(data)
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

func ensureOutputDir(dir string, force bool) error {
	info, err := os.Stat(dir)
	switch {
	case errors.Is(err, os.ErrNotExist):
		return os.MkdirAll(dir, 0o755)
	case err != nil:
		return err
	case !info.IsDir():
		return fmt.Errorf("--output %s exists and is not a directory", dir)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	if len(entries) > 0 && !force {
		return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
	}
	return nil
}

// ValidateTemplateName reports whether name is safe to use as a template
// directory — the exported half of validateTemplateName for callers that
// resolve a library themselves (the dashboard's template endpoints) and need
// the same refusal before joining user input into a path.
func ValidateTemplateName(name string) error {
	return validateTemplateName(name)
}

// validateTemplateName rejects empty names and anything that could escape the
// library checkout root via filepath.Join (separators, parent refs, hidden
// directories). The template argument is user input that we turn directly into
// a path segment, so it has to be sanitized.
func validateTemplateName(name string) error {
	if name == "" {
		return errors.New("template name is required")
	}
	if name == "." || name == ".." || strings.HasPrefix(name, ".") {
		return fmt.Errorf("invalid template name %q", name)
	}
	if strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("invalid template name %q (must be a single path segment)", name)
	}
	return nil
}

func selectPrompter(opts *CreateOptions) Prompter {
	return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
}

// AutoPrompter returns a StdinPrompter when interactive prompting is viable:
// noInput is false and stdin is a real terminal. In CI / piped contexts it
// returns nil, so Resolve reports a clean "missing required parameter(s)"
// error instead of hanging on a read.
func AutoPrompter(stdin io.Reader, out io.Writer, noInput bool) Prompter {
	if noInput {
		return nil
	}
	f, ok := stdin.(*os.File)
	if !ok || !isTerminal(f.Fd()) {
		return nil
	}
	return NewStdinPrompter(stdin, out)
}

package template

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"text/template"

	"github.com/Masterminds/sprig/v3"
	"github.com/santhosh-tekuri/jsonschema/v5"
	"gopkg.in/yaml.v3"
)

// StdinValuesPath is the sentinel a caller may pass in the values-file list
// to signal "read a single values document from this reader". It mirrors the
// `-f -` idiom used by helm, kubectl, and curl.
const StdinValuesPath = "-"

// Resolve produces the final value map by layering, in order:
//
//	defaults declared in spec.parameters.properties[*].default
//	--values files (in supplied order; "-" reads one doc from stdin)
//	--set flags (string values, coerced to declared JSON Schema types)
//	prompts for required parameters still missing (when prompter != nil)
//
// stdin is consumed at most once across the files list; passing "-" twice is
// an error. The merged map is then validated against the JSON Schema in
// spec.parameters. Finally, every entry in spec.values is rendered as a Go
// text/template (with sprig) against the merged map and added under its key.
// A spec.values key that collides with a parameter name is rejected.
func Resolve(t *Template, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveWith(t, ResolveOptions{Files: files, Stdin: stdin, Sets: sets, Prompter: prompter})
}

// ResolveLayered is Resolve with an extra base layer that sits between the
// spec.parameters defaults and the --values files. Callers use it to seed
// values from an earlier resolution (e.g. a committed scaffold record) so
// they take effect without re-prompting but still yield to explicit
// --values / --set input.
func ResolveLayered(t *Template, base map[string]any, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveWith(t, ResolveOptions{Base: base, Files: files, Stdin: stdin, Sets: sets, Prompter: prompter})
}

// ResolveOptions is the full input to value resolution. The zero value is
// a bare resolve: schema defaults, then nothing else. Each field names one
// layer or instrument, in the order resolution applies them — Base under
// Files under Sets, Facts informing prefill and prompts, Prompter and
// Notes as the interactive and diagnostic surfaces.
type ResolveOptions struct {
	// Base sits between the schema defaults and the values files. Callers
	// seed it from an earlier resolution (e.g. a committed scaffold record)
	// so it takes effect without re-prompting but yields to explicit input.
	Base map[string]any

	// Facts is the workspace's declared wiring. It changes resolution in
	// two deliberate ways, both overridable with --set/--values:
	//
	//   - prefill: a required parameter with exactly one workspace
	//     candidate resolves to it without prompting, behaving like an
	//     optional parameter with a workspace-derived default. Each
	//     prefill is noted on Notes so the value never lands invisibly.
	//   - prompt suggestions: a parameter with several candidates prompts
	//     with them as a pick list; the prompter's confirmation is the
	//     value.
	//
	// A nil facts index resolves exactly as ResolveLayered always has.
	Facts *WorkspaceFacts

	// Files are --values files in supplied order; "-" reads one document
	// from Stdin (consumed at most once).
	Files []string
	Stdin io.Reader

	// Sets are --set flag values, applied last of the input layers.
	Sets map[string]any

	// Prompter resolves required parameters still missing after every
	// input layer; nil turns a miss into the missing-parameter error.
	Prompter Prompter

	// Notes receives one line per prefilled value — typically stderr. Nil
	// silences the notes, not the prefill.
	Notes io.Writer
}

// ResolveWith is the resolution all of Resolve, ResolveLayered, and the
// create flows share: the input layers in declaration order, prefill and
// prompts for what they leave open, then schema validation and derived
// values.
func ResolveWith(t *Template, opts ResolveOptions) (map[string]any, error) {
	fields := t.Fields()
	byName := indexFields(fields)
	out := map[string]any{}

	applyDefaultValues(fields, out)
	for k, v := range opts.Base {
		out[k] = coerceKnownFieldValue(k, v, byName)
	}
	if err := applyValuesFiles(opts.Files, opts.Stdin, out, byName); err != nil {
		return nil, err
	}
	applySetValues(opts.Sets, out, byName)
	prefill, _ := candidatesByArity(fields, out, opts.Facts)
	applyPrefill(fields, out, prefill, opts.Notes)
	if err := promptForMissingRequired(fields, out, opts.Facts, opts.Prompter); err != nil {
		return nil, err
	}
	if err := validateSchema(t.Spec.Parameters, out); err != nil {
		return nil, fmt.Errorf("parameter validation: %w", err)
	}
	if err := renderDerivedValues(t.Spec.Values, out, byName); err != nil {
		return nil, err
	}

	return out, nil
}

// candidatesByArity computes every open required parameter's workspace
// candidates once and splits them by what they imply: exactly one
// candidate is a prefill pick, several are prompt suggestions. Fields
// already valued — by default, base, --values, or --set — have neither.
// The single computation keeps prefill and prompts reading one snapshot,
// so the two paths can never disagree about what the workspace offers.
func candidatesByArity(fields []FieldSpec, values map[string]any, facts *WorkspaceFacts) (prefill, suggestions map[string][]string) {
	open := make([]FieldSpec, 0, len(fields))
	for _, f := range fields {
		if !f.Required {
			continue
		}
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			continue
		}
		open = append(open, f)
	}
	prefill = map[string][]string{}
	suggestions = map[string][]string{}
	for name, candidates := range Suggest(open, facts, values) {
		if len(candidates) == 1 {
			prefill[name] = candidates
		} else {
			suggestions[name] = candidates
		}
	}
	return prefill, suggestions
}

// applyPrefill resolves the single-candidate picks candidatesByArity
// separated, chaining as it goes: a prefilled topic constrains contract's
// candidates to that topic's contract, so a workspace with one topic
// resolves the whole wiring without a prompt. Each prefill is noted so
// the value never lands invisibly.
func applyPrefill(fields []FieldSpec, values map[string]any, prefill map[string][]string, notes io.Writer) {
	for _, f := range fields {
		candidates, ok := prefill[f.Name]
		if !ok {
			continue
		}
		if v, valued := values[f.Name]; valued && !isEmpty(v) {
			continue
		}
		values[f.Name] = candidates[0]
		if notes != nil {
			fmt.Fprintf(notes, "%s: %s (from workspace; override with --set %s=<value>)\n", f.Name, candidates[0], f.Name)
		}
	}
}

func applyDefaultValues(fields []FieldSpec, values map[string]any) {
	for _, f := range fields {
		if f.Default != nil {
			values[f.Name] = f.Default
		}
	}
}

func applyValuesFiles(files []string, stdin io.Reader, values map[string]any, byName map[string]FieldSpec) error {
	stdinUsed := false
	for _, path := range files {
		if path == StdinValuesPath {
			if stdinUsed {
				return fmt.Errorf("--values - specified more than once (stdin can only be read once)")
			}
			if stdin == nil {
				return fmt.Errorf("--values - specified but no stdin reader provided")
			}
			data, err := io.ReadAll(stdin)
			if err != nil {
				return fmt.Errorf("read values from stdin: %w", err)
			}
			if err := mergeValuesBytes(data, "stdin", values, byName); err != nil {
				return err
			}
			stdinUsed = true
			continue
		}
		if err := mergeValuesFile(path, values, byName); err != nil {
			return err
		}
	}
	return nil
}

func applySetValues(sets map[string]any, values map[string]any, byName map[string]FieldSpec) {
	for k, v := range sets {
		values[k] = coerceKnownFieldValue(k, v, byName)
	}
}

func promptForMissingRequired(fields []FieldSpec, values map[string]any, facts *WorkspaceFacts, prompter Prompter) error {
	missing := missingRequired(fields, values)
	if len(missing) == 0 {
		return nil
	}
	suggestions := suggestMissing(missing, facts, values)
	if prompter == nil {
		return missingRequiredError(missing, suggestions)
	}
	for _, f := range missing {
		f.Suggestions = suggestions[f.Name]
		ans, _, err := prompter.Prompt(f)
		if err != nil {
			return err
		}
		if isEmpty(ans) {
			return fmt.Errorf("required parameter %q has no value", f.Name)
		}
		values[f.Name] = ans
		// Re-derive after every answer, picked or typed: the answered
		// parameter leaves the open set, and its value may constrain what
		// remains (a known topic narrows the contract candidates).
		// Deriving candidates is the prompt loop's invariant — never cache
		// a suggestion list across answers.
		suggestions = suggestMissing(missing, facts, values)
	}
	return nil
}

// suggestMissing derives candidates for the still-open fields from the
// current value map. It is the prompt loop's one derivation point —
// called before the first prompt and again after every answer — so a
// suggestion list never outlives the values it was derived from.
// Answered fields drop out of the open set; the map holds only what a
// prompt or the missing-parameter error can still act on.
func suggestMissing(missing []FieldSpec, facts *WorkspaceFacts, values map[string]any) map[string][]string {
	unresolved := make([]FieldSpec, 0, len(missing))
	for _, f := range missing {
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			continue
		}
		unresolved = append(unresolved, f)
	}
	return Suggest(unresolved, facts, values)
}

// missingRequiredError reports unmet required parameters, appending one
// hint line per field the workspace has candidates for. The hints name
// what --set would accept so a CI failure documents the values the run
// could not ask for.
func missingRequiredError(missing []FieldSpec, suggestions map[string][]string) error {
	names := make([]string, 0, len(missing))
	for _, f := range missing {
		names = append(names, f.Name)
	}
	err := fmt.Sprintf("missing required parameter(s): %s", strings.Join(names, ", "))
	for _, f := range missing {
		if c := suggestions[f.Name]; len(c) > 0 {
			err += fmt.Sprintf("\nknown %s values in this workspace: %s", f.Name, strings.Join(c, ", "))
		}
	}
	return fmt.Errorf("%s", err)
}

func renderDerivedValues(derived map[string]string, values map[string]any, byName map[string]FieldSpec) error {
	for k, expr := range derived {
		if _, collides := byName[k]; collides {
			return fmt.Errorf("spec.values.%s collides with a parameter of the same name", k)
		}
		rendered, err := renderExpr(expr, values)
		if err != nil {
			return fmt.Errorf("spec.values.%s: %w", k, err)
		}
		values[k] = rendered
	}
	return nil
}

func mergeValuesFile(path string, into map[string]any, byName map[string]FieldSpec) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read values file %s: %w", path, err)
	}
	return mergeValuesBytes(data, path, into, byName)
}

func mergeValuesBytes(data []byte, source string, into map[string]any, byName map[string]FieldSpec) error {
	var fileVals map[string]any
	if err := yaml.Unmarshal(data, &fileVals); err != nil {
		return fmt.Errorf("parse values from %s: %w", source, err)
	}
	for k, v := range fileVals {
		into[k] = coerceKnownFieldValue(k, v, byName)
	}
	return nil
}

func coerceKnownFieldValue(name string, value any, byName map[string]FieldSpec) any {
	field, ok := byName[name]
	if !ok {
		return value
	}
	str, ok := value.(string)
	if !ok {
		return value
	}
	return coerce(str, field.Type)
}

func indexFields(fields []FieldSpec) map[string]FieldSpec {
	m := make(map[string]FieldSpec, len(fields))
	for _, f := range fields {
		m[f.Name] = f
	}
	return m
}

func missingRequired(fields []FieldSpec, values map[string]any) []FieldSpec {
	var missing []FieldSpec
	for _, f := range fields {
		if !f.Required {
			continue
		}
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			continue
		}
		missing = append(missing, f)
	}
	return missing
}

func validateSchema(schema map[string]any, values map[string]any) error {
	raw, err := json.Marshal(schema)
	if err != nil {
		return err
	}
	c := jsonschema.NewCompiler()
	if err := c.AddResource("inline://params.json", bytes.NewReader(raw)); err != nil {
		return err
	}
	s, err := c.Compile("inline://params.json")
	if err != nil {
		return err
	}
	return s.Validate(values)
}

// compileExpr parses a Go text/template string with sprig helpers and
// missingkey=error, so an undefined value name is a loud failure rather than a
// silently empty string. Separate from renderExpr because spec.files rules are
// parsed at load time to reject a syntax error early, and only evaluated later
// once values exist.
func compileExpr(expr string) (*template.Template, error) {
	return template.New("expr").
		Funcs(sprig.TxtFuncMap()).
		Option("missingkey=error").
		Parse(expr)
}

// renderExpr renders a Go text/template string (with sprig) against the
// supplied data map. Used for spec.values entries and spec.files conditions.
func renderExpr(expr string, data map[string]any) (string, error) {
	tmpl, err := compileExpr(expr)
	if err != nil {
		return "", err
	}
	var sb strings.Builder
	if err := tmpl.Execute(&sb, data); err != nil {
		return "", err
	}
	return sb.String(), nil
}

// ParseSets converts ["key=value", ...] into a map. Values stay as strings;
// Resolve coerces them to the JSON Schema type when the key matches a known
// parameter.
func ParseSets(items []string) (map[string]any, error) {
	out := map[string]any{}
	for _, item := range items {
		i := strings.Index(item, "=")
		if i <= 0 {
			return nil, fmt.Errorf("invalid --set %q (expected key=value)", item)
		}
		out[item[:i]] = item[i+1:]
	}
	return out, nil
}

func isEmpty(v any) bool {
	switch t := v.(type) {
	case nil:
		return true
	case string:
		return t == ""
	default:
		return false
	}
}

// Package topology models the declared system topology an integration
// system's host emits. The record declares the system's shape: its components
// (blocks) and the wiring between them, expressed inline on each component —
// the topics it subscribes to and publishes on, the API contracts it provides
// and consumes, and the external ports it uses. Top-level topics[] and
// ports[] sections carry the shared metadata (contracts, external systems)
// those inline references point at.
//
// The record carries only minted facts: the Dapr binding a port deploys as
// (its spec.type, address, credentials) is environment-owned deployment
// configuration in the GitOps repo, and an extractor's cadence is its CronJob
// there. Neither appears here.
//
// The CLI never derives a topology itself: the system host's `graph` verb
// prints the record — JSON only, on stdout — and consumers decode that stream.
package topology

import (
	"encoding/json"
	"fmt"
	"io"
)

const (
	// APIVersion is the topology schema this CLI understands. A record with
	// any other apiVersion is an error, not a guess.
	APIVersion = "topology.intropy.io/v1"

	// Kind is the expected document kind under APIVersion.
	Kind = "SystemTopology"
)

// Topology is one system's declared graph. Wiring is inlined on each component
// rather than kept in a separate edge list: a component names the topics it
// subscribes to and publishes on and the ports it uses. The top-level Topics
// and Ports sections are lookup tables the inline references resolve against
// (contract, external system).
type Topology struct {
	APIVersion string      `json:"apiVersion"`
	Kind       string      `json:"kind,omitempty"`
	System     string      `json:"system"`
	Components []Component `json:"components,omitempty"`
	Topics     []Topic     `json:"topics,omitempty"`
	Ports      []Port      `json:"ports,omitempty"`
	Contracts  []Contract  `json:"contracts,omitempty"`
	// APIs, and each component's Provides/Consumes below, are the contract
	// (request/response) surfaces. Their element shape is not yet finalized,
	// so they are parsed opaquely: preserved for round-tripping to the
	// frontend without asserting a schema the CLI does not yet render.
	APIs []json.RawMessage `json:"apis,omitempty"`
	// Development is the host's local-run picture, present only when the
	// graph verb ran with --development against a host whose Intropy.Topology
	// is new enough to emit it. A nil Development means "no dev configuration
	// known" — older hosts, hosts without a development definition, and plain
	// graph runs all decode identically.
	Development *Development `json:"development,omitempty"`
}

// Development is the development section of a topology record: the host
// author's local substitutions, emitted by `graph --development`.
type Development struct {
	// Files maps an external port to the local folder that stands in for it
	// on a developer machine (the localstorage binding's root).
	Files []FilePort `json:"files,omitempty"`
}

// FilePort is one port's development file resolution. RootPath is declared
// relative to the system host's directory ("./test/erp-source"); the host
// library rejects paths that escape it, and consumers confine again before
// writing.
type FilePort struct {
	Port     string `json:"port"`
	RootPath string `json:"rootPath"`
}

// Component is a deployable block of the system. Kind is the block type
// (extractor, loader, transactional-integration, …). A component's directory,
// which joins it to its .intropy/scaffold.json project, is its Name relative
// to the system root.
type Component struct {
	Name       string        `json:"name"`
	Kind       string        `json:"kind"`
	Subscribes []TopicRef    `json:"subscribes,omitempty"`
	Publishes  []Publication `json:"publishes,omitempty"`
	Ports      []PortUse     `json:"ports,omitempty"`
	// Provides/Consumes are contract surfaces, parsed opaquely (see APIs).
	Provides []json.RawMessage `json:"provides,omitempty"`
	Consumes []json.RawMessage `json:"consumes,omitempty"`
}

// TopicRef is a component's subscription to a pub/sub topic.
type TopicRef struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// Publication is a component's output onto a pub/sub topic.
type Publication struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// PortUse is a component's use of an external port. Direction is "in"
// (external → component) or "out" (component → external).
type PortUse struct {
	Port      string `json:"port"`
	Direction string `json:"direction"`
}

// Topic is a declared pub/sub topic: the metadata for a (PubSub, Topic) pair
// components reference. Contract is the message contract it carries;
// Publishers/Subscribers name the components on each end.
type Topic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Contract is a message contract in the system's registry, keyed by Name —
// the same fully-qualified type name Topic.Contract references. ShortName is
// the bare type name (the join key to a scaffold record's values.contract).
// Schema is the contract's JSON Schema as the host emitted it; the CLI passes
// it through to the frontend without interpreting it. Fingerprint identifies
// the schema shape (a hash over its canonical form), so equal fingerprints
// mean equal shapes across systems.
type Contract struct {
	Name        string          `json:"name"`
	Kind        string          `json:"kind,omitempty"`
	ShortName   string          `json:"shortName,omitempty"`
	MediaType   string          `json:"mediaType,omitempty"`
	Fingerprint string          `json:"fingerprint,omitempty"`
	Schema      json.RawMessage `json:"schema,omitempty"`
}

// Port is an external system integration point. The name is its whole
// identity — the deployed Dapr binding type, address, and credentials are
// environment-owned deployment configuration, never part of the record.
// ExternalSystem is the system it fronts, Directions the directions it is
// wired in, and UsedBy the components that use it.
type Port struct {
	Name           string   `json:"name"`
	ExternalSystem string   `json:"externalSystem,omitempty"`
	Directions     []string `json:"directions,omitempty"`
	UsedBy         []string `json:"usedBy,omitempty"`
}

// Entry is one system's topology plus the workspace directory it belongs to,
// flattened into one self-describing JSON document for the API.
type Entry struct {
	Path string `json:"path"`
	Topology
}

// Decode parses a topology record from r (typically a host `graph` verb's
// stdout). A record whose apiVersion this CLI does not understand is an
// error, not a guess. Callers wrap the error with the record's origin.
func Decode(r io.Reader) (*Topology, error) {
	var t Topology
	if err := json.NewDecoder(r).Decode(&t); err != nil {
		return nil, fmt.Errorf("parse topology record: %w", err)
	}
	if t.APIVersion != APIVersion {
		return nil, fmt.Errorf("unsupported topology apiVersion %q (this CLI understands %q)",
			t.APIVersion, APIVersion)
	}
	return &t, nil
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"text/tabwriter"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/spf13/cobra"
)

// int list walks a directory tree for scaffold records. The walk and the
// record parsing live in internal/template; this file is flag plumbing and
// table formatting.
type intListFlags struct {
	output string
}

var intListOpts intListFlags

var intListCmd = &cobra.Command{
	Use:   "list [dir]",
	Short: "List scaffolded integrations under a directory",
	Long: "Walk the directory tree from dir (default: the current directory) and list every project carrying a " +
		template.ScaffoldRelPath + " record written by `int create`. " +
		"Matched projects are not descended into, and .git, .intropy, node_modules, bin and dist are skipped. " +
		"Use --output json for a machine-readable document including the pinned source and scaffold values.",
	Args: usageArgs(cobra.MaximumNArgs(1)),
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(intListOpts.output, "json", "plain"); err != nil {
			return err
		}
		root := "."
		if len(args) == 1 {
			root = args[0]
		}
		if info, err := os.Stat(root); err != nil {
			return fmt.Errorf("list: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("list: %s is not a directory", root)
		}

		entries, warnings := template.ListScaffolds(root)
		for _, w := range warnings {
			fmt.Fprintln(cmd.ErrOrStderr(), "warning:", w)
		}

		if intListOpts.output == "json" {
			if entries == nil {
				entries = []template.ScaffoldEntry{}
			}
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(entries)
		}

		if len(entries) == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "no scaffolded integrations found")
			return nil
		}

		tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
		fmt.Fprintln(tw, "PATH\tTEMPLATE\tVERSION")
		for _, e := range entries {
			fmt.Fprintf(tw, "%s\t%s\t%s\n", e.Path, e.Template, e.Version)
		}
		return tw.Flush()
	},
}

func init() {
	f := intListCmd.Flags()
	f.StringVarP(&intListOpts.output, "output", "o", "plain", flagUsageOutput)
	intCmd.AddCommand(intListCmd)
}

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// TemplateRoleLabel names the manifest label that declares what role a
	// template's output plays in a system. Its value is copied into the
	// scaffold record so later commands can tell support projects apart
	// from system blocks.
	TemplateRoleLabel = "intropy.dev/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel = "intropy.dev/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in", "out",
	// or "both"). Recorded alongside the block kind.
	TemplateDataFlowLabel = "intropy.dev/data-flow"

	// The BlockKind constants name the block kinds with a parse entry in
	// internal/system's blockParsers registry — the set `sys create`
	// assembles. Records carrying any other kind are skipped with a
	// warning.
	BlockKindExtractor     = "extractor"
	BlockKindLoader        = "loader"
	BlockKindTransactional = "transactional-integration"
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g. `sys
// create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int            `json:"schemaVersion"`
	Template      string         `json:"template"` // directory name in the template library repo
	Owner         string         `json:"owner"`
	Repo          string         `json:"repo"`
	Version       string         `json:"version"`
	Values        map[string]any `json:"values"`

	// Role is the value of the template's intropy.dev/template-role label,
	// if any (e.g. "shared-library").
	Role string `json:"role,omitempty"`

	// BlockKind is the value of the template's intropy.dev/block-kind
	// label, if any (e.g. "extractor").
	BlockKind string `json:"blockKind,omitempty"`

	// DataFlow is the value of the template's intropy.dev/data-flow label,
	// if any ("in" or "out").
	DataFlow string `json:"dataFlow,omitempty"`

	// DependsOn lists the sibling projects this project's template declared
	// under spec.dependencies, whether the render created them or they
	// already existed.
	DependsOn []DependencyRecord `json:"dependsOn,omitempty"`
}

// DependencyRecord points at a sibling project a component depends on. Dir
// is slash-separated and relative to the component root (e.g. "../Acme.Models").
type DependencyRecord struct {
	Template string `json:"template"`
	Dir      string `json:"dir"`
}

func roleFromLabels(labels map[string]string) string {
	return labels[TemplateRoleLabel]
}

func blockKindFromLabels(labels map[string]string) string {
	return labels[TemplateBlockKindLabel]
}

func dataFlowFromLabels(labels map[string]string) string {
	return labels[TemplateDataFlowLabel]
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}

package template

import (
	"bufio"
	"fmt"
	"io"
	"regexp"
	"strconv"
	"strings"

	"golang.org/x/term"
)

// Prompter resolves one missing required field with the user. The
// applied result reports whether a field Suggestion produced the value
// (shown default accepted, or a list pick) as opposed to the user typing
// it fresh. Resolution re-derives candidates after every answer
// regardless; the flag exists for prompters and callers that distinguish
// a confirmation from a novel entry.
type Prompter interface {
	Prompt(field FieldSpec) (value any, applied bool, err error)
}

// StdinPrompter is a line-based prompter. Enums render as a numbered list;
// every other type flows through one read-coerce-validate-retry loop.
// Invalid input re-prompts; EOF aborts.
//
// Suggestions change the rendering, never the authority: one suggestion
// becomes the shown default (Enter accepts, typing overrides), several
// render as a numbered list that still accepts a fresh value. Only an
// accepted or picked suggestion is reported applied.
type StdinPrompter struct {
	in      io.Reader
	out     io.Writer
	scanner *bufio.Scanner
}

func NewStdinPrompter(in io.Reader, out io.Writer) *StdinPrompter {
	return &StdinPrompter{in: in, out: out, scanner: bufio.NewScanner(in)}
}

func (p *StdinPrompter) Prompt(f FieldSpec) (any, bool, error) {
	if len(f.Suggestions) > 0 && len(f.Enum) == 0 {
		return p.promptSuggested(f)
	}
	if len(f.Enum) > 0 {
		v, err := p.promptEnum(f)
		return v, false, err
	}
	v, err := p.promptScalar(f)
	return v, false, err
}

// promptSuggested handles a scalar field with workspace-derived
// candidates. A single candidate is the prompt default; several render as
// a pick list that stays open — a scaffold's whole point may be a topic
// nobody has declared yet, so the list never replaces free input.
func (p *StdinPrompter) promptSuggested(f FieldSpec) (any, bool, error) {
	if len(f.Suggestions) == 1 {
		v, err := p.promptScalar(withDefault(f, f.Suggestions[0]))
		if err != nil {
			return nil, false, err
		}
		if s, ok := v.(string); ok && s == f.Suggestions[0] {
			return v, true, nil
		}
		return v, false, nil
	}
	return p.promptSuggestedList(f)
}

// promptSuggestedList renders candidates as a numbered list plus a
// free-text escape, reusing the enum prompt's read-validate-retry loop
// with one difference: input that matches no candidate is a new value,
// not an error.
func (p *StdinPrompter) promptSuggestedList(f FieldSpec) (any, bool, error) {
	p.writeHeading(f)
	for i, s := range f.Suggestions {
		fmt.Fprintf(p.out, "  %d) %s\n", i+1, s)
	}
	fmt.Fprintln(p.out, "  or type a new value")
	for {
		fmt.Fprint(p.out, ": ")
		raw, ok, err := p.readLine()
		if err != nil {
			return nil, false, err
		}
		if !ok {
			return nil, false, io.EOF
		}
		if raw == "" {
			fmt.Fprintln(p.out, "  ! please choose one")
			continue
		}
		if n, err := strconv.Atoi(raw); err == nil && n >= 1 && n <= len(f.Suggestions) {
			return coerce(f.Suggestions[n-1], f.Type), true, nil
		}
		for _, s := range f.Suggestions {
			if raw == s {
				return coerce(s, f.Type), true, nil
			}
		}
		v := coerce(raw, f.Type)
		if err := p.validateScalar(f, v); err != nil {
			fmt.Fprintf(p.out, "  ! %s\n", err)
			continue
		}
		return v, false, nil
	}
}

func (p *StdinPrompter) promptScalar(f FieldSpec) (any, error) {
	for {
		p.writeLabel(f)
		raw, ok, err := p.readLine()
		if err != nil {
			return nil, err
		}
		if !ok {
			return nil, io.EOF
		}
		if raw == "" {
			return f.Default, nil
		}
		v := coerce(raw, f.Type)
		if err := p.validateScalar(f, v); err != nil {
			fmt.Fprintf(p.out, "  ! %s\n", err)
			continue
		}
		return v, nil
	}
}

// validateScalar is the retry-condition half of promptScalar, shared with
// the free-text path of a suggestion list: typed fields must parse, and a
// declared pattern must match.
func (p *StdinPrompter) validateScalar(f FieldSpec, v any) error {
	if isTypedField(f.Type) {
		if _, stillStr := v.(string); stillStr {
			return fmt.Errorf("%v is not a valid %s", v, f.Type)
		}
	}
	if f.Pattern != "" {
		re, err := regexp.Compile(f.Pattern)
		if err != nil {
			return fmt.Errorf("invalid pattern for %q: %w", f.Name, err)
		}
		s, ok := v.(string)
		if !ok || !re.MatchString(s) {
			return fmt.Errorf("value must match %s", f.Pattern)
		}
	}
	return nil
}

func (p *StdinPrompter) promptEnum(f FieldSpec) (any, error) {
	p.writeHeading(f)
	options := make([]string, 0, len(f.Enum))
	for i, e := range f.Enum {
		s := fmt.Sprint(e)
		options = append(options, s)
		fmt.Fprintf(p.out, "  %d) %s\n", i+1, s)
	}
	defStr, hasDef := f.Default.(string)
	for {
		if hasDef {
			fmt.Fprintf(p.out, "[%s]: ", defStr)
		} else {
			fmt.Fprint(p.out, ": ")
		}
		raw, ok, err := p.readLine()
		if err != nil {
			return nil, err
		}
		if !ok {
			return nil, io.EOF
		}
		if raw == "" {
			if hasDef {
				return coerce(defStr, f.Type), nil
			}
			fmt.Fprintln(p.out, "  ! please choose one")
			continue
		}
		if n, err := strconv.Atoi(raw); err == nil && n >= 1 && n <= len(options) {
			return coerce(options[n-1], f.Type), nil
		}
		for _, o := range options {
			if o == raw {
				return coerce(o, f.Type), nil
			}
		}
		fmt.Fprintf(p.out, "  ! %q is not one of the options\n", raw)
	}
}

func (p *StdinPrompter) writeLabel(f FieldSpec) {
	label := f.Name
	if f.Title != "" {
		label = f.Title
	}
	if f.Description != "" {
		label = fmt.Sprintf("%s (%s)", label, f.Description)
	}
	switch d := f.Default.(type) {
	case bool:
		if d {
			label += " [Y/n]"
		} else {
			label += " [y/N]"
		}
	case nil:
		if f.Type == "boolean" {
			label += " [y/n]"
		}
	default:
		label = fmt.Sprintf("%s [%v]", label, d)
	}
	fmt.Fprintf(p.out, "%s: ", label)
}

func (p *StdinPrompter) writeHeading(f FieldSpec) {
	title := f.Name
	if f.Title != "" {
		title = f.Title
	}
	if f.Description != "" {
		fmt.Fprintf(p.out, "%s (%s)\n", title, f.Description)
	} else {
		fmt.Fprintln(p.out, title)
	}
}

func (p *StdinPrompter) readLine() (string, bool, error) {
	if !p.scanner.Scan() {
		if err := p.scanner.Err(); err != nil {
			return "", false, err
		}
		return "", false, nil
	}
	return strings.TrimSpace(p.scanner.Text()), true, nil
}

// withDefault returns a copy of the field whose shown default is the
// suggestion. The schema default already lost the bracket when suggestions
// were computed (Suggest drops candidates equal to it), so overwriting is
// safe for the prompt's lifetime.
func withDefault(f FieldSpec, suggestion string) FieldSpec {
	f.Default = suggestion
	return f
}

func isTypedField(typ string) bool {
	return typ == "boolean" || typ == "integer" || typ == "number"
}

// coerce parses a string into the type declared by a JSON Schema property.
// Returns the original string if parsing fails — JSON Schema validation
// downstream produces a clean type error in that case.
func coerce(s, typ string) any {
	switch typ {
	case "boolean":
		switch strings.ToLower(s) {
		case "y", "yes", "true", "1":
			return true
		case "n", "no", "false", "0":
			return false
		}
	case "integer":
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return i
		}
	case "number":
		if v, err := strconv.ParseFloat(s, 64); err == nil {
			return v
		}
	}
	return s
}

func isTerminal(fd uintptr) bool {
	return term.IsTerminal(int(fd))
}

package template

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// PreparedCreate is a create run with everything resolved and nothing written:
// the manifest, the resolved values, the skeleton root, the release it came
// from, and the cleanup that removes the extracted library. RunCreate turns it
// into files on disk.
//
// It exists for callers that fetch the library themselves — the dashboard
// resolves one release for a whole form session and renders against that,
// where Create would re-resolve (and re-download) per request. The caller owns
// Cleanup and must call it once the run is done.
type PreparedCreate struct {
	// Template is the repo directory name of the requested template — what a
	// later re-fetch needs, as on CreateResult.
	Template string

	// Manifest is the template's parsed manifest.
	Manifest *Template

	// Values are the fully resolved render values.
	Values map[string]any

	// SkeletonRoot is the extracted skeleton/ directory Render reads.
	SkeletonRoot string

	// RepoRoot is the extracted library root, so dependency renders find the
	// sibling templates of the same release.
	RepoRoot string

	// Owner, Repo and Version describe the library the template came from.
	Owner   string
	Repo    string
	Version string

	// Cleanup is retained for callers that hold a prepared create across a
	// session; the checkout lives in the shared cache, so it is a no-op.
	Cleanup func()
}

// PrepareCreate fetches the named template at the requested version (or
// latest) and resolves its values, stopping before any output is written —
// the first half of Create. Files and SetValues feed Resolve exactly as
// Create's --values and --set do; a nil prompter makes a missing required
// value the clean "missing required parameter(s)" error rather than a prompt.
func PrepareCreate(ctx context.Context, opts CreateOptions) (*PreparedCreate, error) {
	opts.applyDefaults()
	if err := validateTemplateName(opts.Template); err != nil {
		return nil, err
	}

	src, err := FetchSource(ctx, opts.sourceOpts())
	if err != nil {
		return nil, err
	}

	templateRoot, err := templateDir(src, src.Owner, src.Repo, opts.Template)
	if err != nil {
		return nil, err
	}

	tmpl, values, err := prepareCreateTemplate(templateRoot, opts)
	if err != nil {
		return nil, err
	}

	skelRoot := filepath.Join(templateRoot, templateSkeletonDir)
	if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
		return nil, fmt.Errorf("template %q is missing %s/ directory", opts.Template, templateSkeletonDir)
	}

	return &PreparedCreate{
		Template:     opts.Template,
		Manifest:     tmpl,
		Values:       values,
		SkeletonRoot: skelRoot,
		RepoRoot:     filepath.Dir(templateRoot),
		Owner:        src.Owner,
		Repo:         src.Repo,
		Version:      src.Version,
		Cleanup:      func() {},
	}, nil
}

// RunCreate executes the second half of Create: render the skeleton into
// outputDir, process declared dependencies, record the scaffold, and return
// the machine-readable result. The prompter question is already settled —
// PrepareCreate resolved the values — so RunCreate never interacts.
func RunCreate(p *PreparedCreate, outputDir string, force bool, stderr io.Writer) (*CreateResult, error) {
	if outputDir == "" {
		return nil, errors.New("--out-dir is required")
	}
	if stderr == nil {
		stderr = io.Discard
	}

	if err := renderCreateOutput(p.SkeletonRoot, p.Manifest, p.Template, outputDir, force, p.Values); err != nil {
		return nil, err
	}
	fmt.Fprintf(stderr, "created %s from %s/%s@%s (template %s)\n", outputDir, p.Owner, p.Repo, p.Version, p.Template)

	// Dependencies come from the same library checkout, so they are always
	// version-locked to the component that declared them.
	depRecords, depResults, err := processDependencies(p.Manifest, p.Values, outputDir, &depContext{
		repoRoot: p.RepoRoot,
		owner:    p.Owner,
		repo:     p.Repo,
		version:  p.Version,
		stderr:   stderr,
		visited:  map[string]bool{},
	}, 0)
	if err != nil {
		return nil, err
	}

	// The template field is the repo directory name (p.Template), not
	// p.Manifest.Metadata.Name — it is what a later re-fetch needs.
	if err := WriteScaffold(outputDir, Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      p.Template,
		Owner:         p.Owner,
		Repo:          p.Repo,
		Version:       p.Version,
		Values:        p.Values,
		Role:          roleFromLabels(p.Manifest.Metadata.Labels),
		BlockKind:     blockKindFromLabels(p.Manifest.Metadata.Labels),
		DataFlow:      dataFlowFromLabels(p.Manifest.Metadata.Labels),
		DependsOn:     depRecords,
	}); err != nil {
		return nil, err
	}

	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		absOut = outputDir
	}
	return &CreateResult{
		Template:     p.Manifest.Metadata.Name,
		Owner:        p.Owner,
		Repo:         p.Repo,
		Version:      p.Version,
		OutputDir:    absOut,
		Values:       p.Values,
		Dependencies: depResults,
	}, nil
}

// Package system assembles scaffolded integrations into a system host. It
// scans the workspace for the .intropy/scaffold.json records `int create`
// left behind, validates them into a system model, and builds the value
// payload the system-host template renders every declaration file from —
// Topics.cs, Ports.cs, the development and system definitions, and
// the csproj. The template library owns all generated content; this
// package owns workspace knowledge only.
package system

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// hostTemplate is the directory in the templates repo holding the system
// host: the shell plus every declaration file, rendered from the payload.
const hostTemplate = "system-host"

type CreateOptions struct {
	Name       string // system name as typed; PascalCase or kebab-case
	StartDir   string // workspace scan root; default "."
	OutputDir  string // default: the kebab-cased name
	Version    string // template release tag; default: latest
	Force      bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library; zero values target the
	// official library. Source carries the fetch seams (GitHubBaseURL
	// redirects the latest-release API call in tests).
	Owner  string
	Repo   string
	Source template.SourceOptions
}

// minFactsPayloadVersion is the lowest template-library release whose
// system-host consumes the facts-only payload. Named in the version gate's
// error so a user on an older release knows the floor.
const minFactsPayloadVersion = "v0.4.0"

// CreateResult is the machine-readable summary written when --output-json
// is set. Field names are stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`
	System    Summary        `json:"system"`
}

// Summary describes the assembled system; it loosely mirrors the model the
// host's `graph` verb prints.
type Summary struct {
	Name          string      `json:"name"`
	Components    []Component `json:"components"`
	Topics        []Topic     `json:"topics"`
	Ports         []Port      `json:"ports,omitempty"`
	SharedLibrary string      `json:"sharedLibrary"` // scaffold directory
}

func (o *CreateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full assembly: scan the workspace for scaffold records,
// validate them into a system model, build the value payload, and render
// the system-host template with it. All local validation happens before
// any network I/O.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if opts.Name == "" {
		return fmt.Errorf("a system name is required")
	}

	// Exact parity with the templates' `{{ .name | kebabcase }}`: sprig
	// delegates to xstrings, so OrderFlow and order-flow are equivalent.
	kebab := xstrings.ToKebabCase(opts.Name)
	if opts.OutputDir == "" {
		opts.OutputDir = kebab
	}

	entries, warnings := template.ListScaffolds(opts.StartDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	warnf := func(format string, args ...any) {
		fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
	}
	model, err := Assemble(entries, warnf)
	if err != nil {
		return err
	}
	model.Name = kebab

	payload, err := buildPayload(model, opts.OutputDir, kebab)
	if err != nil {
		return err
	}

	if err := template.Create(ctx, template.CreateOptions{
		Template:   hostTemplate,
		OutputDir:  opts.OutputDir,
		Version:    opts.Version,
		SetValues:  payload,
		Force:      opts.Force,
		NoInput:    true, // the template's values come from the payload, never prompts
		OnManifest: requireFactsPayload,
		Stdin:      strings.NewReader(""),
		Stdout:     opts.Stdout,
		Stderr:     opts.Stderr,
		HTTP:       opts.HTTP,
		UserAgent:  opts.UserAgent,
		Owner:      opts.Owner,
		Repo:       opts.Repo,
		Source:     opts.Source,
	}); err != nil {
		return err
	}

	// The template derives projectName/systemClass from the name; reading
	// them back from the record it just wrote keeps the result summary
	// honest about what was rendered.
	record, err := template.LoadScaffold(filepath.Join(opts.OutputDir, filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		return err
	}
	hostEntry := template.ScaffoldEntry{Path: opts.OutputDir, Scaffold: *record}
	if model.ProjectName, err = template.RecordValue(hostEntry, template.KeyProjectName); err != nil {
		return fmt.Errorf("template %s did not derive the host project name: %w", hostTemplate, err)
	}
	if model.SystemClass, err = template.RecordValue(hostEntry, template.KeySystemClass); err != nil {
		return fmt.Errorf("template %s did not derive the system class name: %w", hostTemplate, err)
	}

	contracts := "no contracts project"
	if model.Shared != nil {
		contracts = "contracts from " + model.Shared.Path
	}
	fmt.Fprintf(opts.Stderr, "assembled system %q: %d component(s), %d topic(s), %d port(s), %s\n",
		model.Name, len(model.Components), len(model.Topics), len(model.Ports), contracts)

	return maybeWriteCreateResult(opts, record, model)
}

// requireFactsPayload rejects a system-host template release that predates
// the facts-only payload: one that still requires sharedContracts consumes
// the pre-join payload shape (CLI-derived field identifiers and a csproj
// include path), which this CLI no longer produces. The gate runs before any
// output is written so an old release fails loudly instead of rendering a
// host that cannot compile.
func requireFactsPayload(t *template.Template) error {
	required, _ := t.Spec.Parameters["required"].([]any)
	for _, r := range required {
		if name, _ := r.(string); name == "sharedContracts" {
			return fmt.Errorf("system-host template %s requires the sharedContracts payload: it predates facts-only payloads (field identifiers and the csproj reference moved into the template) — use template release %s or newer", t.Metadata.Name, minFactsPayloadVersion)
		}
	}
	return nil
}

// sharedPath reports the detected contracts sibling for the JSON summary;
// empty when the workspace has none.
func sharedPath(m *Model) string {
	if m.Shared == nil {
		return ""
	}
	return m.Shared.Path
}

func maybeWriteCreateResult(opts CreateOptions, record *template.Scaffold, model *Model) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:  hostTemplate,
		Owner:     record.Owner,
		Repo:      record.Repo,
		Version:   record.Version,
		OutputDir: absOut,
		Values:    record.Values,
		System: Summary{
			Name:          model.Name,
			Components:    model.Components,
			Topics:        model.Topics,
			Ports:         model.Ports,
			SharedLibrary: sharedPath(model),
		},
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output-json: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

package main

import "fmt"

// usageError wraps an error to signal that it should map to exit code 2.
// Use this for invalid arguments, missing flags, and other caller mistakes.
type usageError struct {
	err error
}

func (e *usageError) Error() string {
	return e.err.Error()
}

func (e *usageError) Unwrap() error {
	return e.err
}

// newUsageErrorf creates a usageError with formatted text.
func newUsageErrorf(format string, args ...any) error {
	return &usageError{err: fmt.Errorf(format, args...)}
}

package system

import (
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// LoadWorkspaceFacts scans root for scaffold records and indexes what they
// declare into prompt-time workspace facts. Warnings are non-fatal: one
// malformed record must not hide the facts the rest of the workspace
// carries, and a suggestion aid never aborts the create it assists. A
// missing or record-free root yields an empty index.
func LoadWorkspaceFacts(root string) (*template.WorkspaceFacts, []error) {
	entries, warnings := template.ListScaffolds(root)
	return WorkspaceFactsOf(entries), warnings
}

// WorkspaceFactsOf adapts scanned scaffold records into the fact index,
// dropping records that carry no block wiring (shared libraries, system
// hosts) before indexing.
func WorkspaceFactsOf(entries []template.ScaffoldEntry) *template.WorkspaceFacts {
	factEntries := make([]template.WorkspaceFactEntry, 0, len(entries))
	for _, e := range entries {
		if e.BlockKind == "" {
			continue
		}
		factEntries = append(factEntries, template.WorkspaceFactEntry{
			BlockKind: e.BlockKind,
			Values:    e.Values,
		})
	}
	return template.BuildWorkspaceFacts(factEntries)
}

package template

import (
	"fmt"
	"os"
	"regexp"

	"gopkg.in/yaml.v3"
)

const (
	APIVersionV1 = "intropy.dev/v1"
	KindTemplate = "Template"
)

// Template is the on-disk manifest for a template. The envelope mirrors the
// Kubernetes / Backstage shape so authors recognize it at a glance; the body
// is a deliberately narrow subset (no ui: extensions, no step pipeline).
type Template struct {
	APIVersion string   `yaml:"apiVersion"`
	Kind       string   `yaml:"kind"`
	Metadata   Metadata `yaml:"metadata"`
	Spec       Spec     `yaml:"spec"`
}

type Metadata struct {
	Name        string            `yaml:"name"`
	Title       string            `yaml:"title,omitempty"`
	Description string            `yaml:"description,omitempty"`
	Tags        []string          `yaml:"tags,omitempty"`
	Labels      map[string]string `yaml:"labels,omitempty"`
}

type Spec struct {
	Parameters   map[string]any    `yaml:"parameters"`
	Values       map[string]string `yaml:"values,omitempty"`
	Files        []FileRule        `yaml:"files,omitempty"`
	Dependencies []DependencySpec  `yaml:"dependencies,omitempty"`

	// Local declares what a local-cluster render of this template offers.
	// Absent on templates that are never rendered locally; on deploy-component
	// it is how the fixture catalog travels with the release rather than being
	// hardcoded in the CLI.
	Local *LocalSpec `yaml:"local,omitempty"`

	// GitOps declares the GitOps-specific catalog on deploy-host. It stays
	// separate from Local because a GitOps binding kind is not a local fixture.
	GitOps *GitOpsSpec `yaml:"gitops,omitempty"`

	// parameterOrder captures the declaration order of properties in
	// spec.parameters.properties, since Go maps don't preserve YAML order.
	// Populated by UnmarshalYAML.
	parameterOrder []string
}

// FileRule conditionally includes part of a skeleton, so one template can serve
// platforms whose manifest sets differ rather than only whose values differ.
//
// Path is a slash-separated glob relative to skeleton/, matched against the
// *source* path with any .tmpl suffix included — a rule that decides on values
// cannot depend on a path those values produce, so a templated directory segment
// is only reachable via a glob. A trailing "/**" also matches everything beneath
// the directory, and prunes it before its contents are parsed.
//
// When is a Go template (sprig available) rendered against the resolved values.
// Any result other than "", "false" or "0" includes the match.
//
// The first rule whose Path matches decides, and a path no rule matches is
// included — so a template without spec.files renders exactly as it did before
// this field existed.
type FileRule struct {
	Path string `yaml:"path" json:"path"`
	When string `yaml:"when" json:"when"`
}

// DependencySpec declares another template in the same library that must
// exist as a sibling of this template's output. Create renders it when the
// target directory is missing and skips it when a scaffold record from the
// same template is already there, so a shared project is created exactly
// once no matter how many components declare it.
type DependencySpec struct {
	// Template is the dependency's directory name in the templates repo.
	Template string `yaml:"template" json:"template"`
	// Output is a Go template (with sprig) rendered against the parent's
	// resolved values. It must produce a single path segment; the dependency
	// is created as a sibling of the parent's output directory.
	Output string `yaml:"output" json:"output"`
	// Values maps dependency parameter names to Go templates rendered
	// against the parent's resolved values. Dependencies resolve without
	// prompting, so together with the dependency's own defaults these must
	// cover every required parameter.
	Values map[string]string `yaml:"values,omitempty" json:"values,omitempty"`
	// When is an optional Go template (sprig available) rendered against
	// the parent's resolved values, with the same truthiness rules as a
	// spec.files condition. An empty When renders the dependency
	// unconditionally, as before the field existed.
	When string `yaml:"when,omitempty" json:"when,omitempty"`
}

// GitOpsSpec is the GitOps-only part of a template manifest.
type GitOpsSpec struct {
	BindingKinds []string `yaml:"bindingKinds"`
}

// LocalSpec is the local-render section of a template manifest.
//
// Fixtures is the closed catalog of fixture bindings a port can be bound
// to in a local render. The CLI reads it from the fetched library, so the menu
// it presents, the values it accepts and the skeletons it renders all come from
// one release of one repository.
type LocalSpec struct {
	Fixtures []string `yaml:"fixtures"`
}

// fixtureNamePattern keeps a fixture name usable as a path segment, a Dapr
// component name fragment and a map key without escaping anywhere.
var fixtureNamePattern = regexp.MustCompile(`^[a-z0-9][a-z0-9-]*$`)

// UnmarshalYAML decodes the spec and captures property declaration order
// so Fields() can return FieldSpecs in author-intended sequence.
func (s *Spec) UnmarshalYAML(node *yaml.Node) error {
	// Every field of Spec must be repeated here: the decode targets rawSpec, so
	// a field added to Spec alone is silently dropped.
	type rawSpec struct {
		Parameters   map[string]any    `yaml:"parameters"`
		Values       map[string]string `yaml:"values,omitempty"`
		Files        []FileRule        `yaml:"files,omitempty"`
		Dependencies []DependencySpec  `yaml:"dependencies,omitempty"`
		Local        *LocalSpec        `yaml:"local,omitempty"`
		GitOps       *GitOpsSpec       `yaml:"gitops,omitempty"`
	}
	var r rawSpec
	if err := node.Decode(&r); err != nil {
		return err
	}
	s.Parameters = r.Parameters
	s.Values = r.Values
	s.Files = r.Files
	s.Dependencies = r.Dependencies
	s.Local = r.Local
	s.GitOps = r.GitOps
	s.parameterOrder = extractPropertyOrder(node)
	return nil
}

func extractPropertyOrder(specNode *yaml.Node) []string {
	if specNode.Kind != yaml.MappingNode {
		return nil
	}
	paramsNode := childByKey(specNode, "parameters")
	if paramsNode == nil {
		return nil
	}
	propsNode := childByKey(paramsNode, "properties")
	if propsNode == nil || propsNode.Kind != yaml.MappingNode {
		return nil
	}
	order := make([]string, 0, len(propsNode.Content)/2)
	for i := 0; i < len(propsNode.Content); i += 2 {
		order = append(order, propsNode.Content[i].Value)
	}
	return order
}

func childByKey(mapping *yaml.Node, key string) *yaml.Node {
	if mapping.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i < len(mapping.Content); i += 2 {
		if mapping.Content[i].Value == key {
			return mapping.Content[i+1]
		}
	}
	return nil
}

// FieldSpec is the prompter/CLI view of a single property in spec.parameters.
// Prompters and form code only consume FieldSpecs — they never touch the raw
// JSON Schema map. The JSON tags make a FieldSpec safe to serve over the wire
// (the dashboard's template form renders from them); they are additive to a
// struct nothing previously marshaled.
type FieldSpec struct {
	Name        string `json:"name"`
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Type        string `json:"type"` // "string" | "boolean" | "integer" | "number"
	Enum        []any  `json:"enum,omitempty"`
	Default     any    `json:"default,omitempty"`
	Pattern     string `json:"pattern,omitempty"`
	Required    bool   `json:"required"`

	// Suggestions carries prompt-time candidate values derived from the
	// workspace the create runs in (see Suggest). It is populated by
	// callers with workspace context — never by manifest loading, which
	// leaves it nil — and it is prompt metadata only: it never enters the
	// values map or the JSON Schema validation the schema fields above do.
	Suggestions []string `json:"suggestions,omitempty"`
}

// Fields returns the JSON Schema properties as FieldSpecs in YAML declaration
// order.
func (t *Template) Fields() []FieldSpec {
	props, _ := t.Spec.Parameters["properties"].(map[string]any)
	if props == nil {
		return nil
	}
	required := map[string]bool{}
	if list, ok := t.Spec.Parameters["required"].([]any); ok {
		for _, r := range list {
			if s, ok := r.(string); ok {
				required[s] = true
			}
		}
	}
	out := make([]FieldSpec, 0, len(t.Spec.parameterOrder))
	for _, name := range t.Spec.parameterOrder {
		raw, _ := props[name].(map[string]any)
		out = append(out, fieldFromSchema(name, raw, required[name]))
	}
	return out
}

func fieldFromSchema(name string, schema map[string]any, required bool) FieldSpec {
	f := FieldSpec{Name: name, Required: required}
	if schema == nil {
		return f
	}
	f.Type, _ = schema["type"].(string)
	f.Title, _ = schema["title"].(string)
	f.Description, _ = schema["description"].(string)
	f.Pattern, _ = schema["pattern"].(string)
	f.Default = schema["default"]
	if e, ok := schema["enum"].([]any); ok {
		f.Enum = e
	}
	return f
}

// LoadTemplate reads and validates a template.yaml file.
func LoadTemplate(path string) (*Template, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read template: %w", err)
	}
	var t Template
	if err := yaml.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("parse template: %w", err)
	}
	if err := t.validate(); err != nil {
		return nil, fmt.Errorf("invalid template: %w", err)
	}
	return &t, nil
}

func (t *Template) validate() error {
	if t.APIVersion != APIVersionV1 {
		return fmt.Errorf("unsupported apiVersion %q (want %q)", t.APIVersion, APIVersionV1)
	}
	if t.Kind != KindTemplate {
		return fmt.Errorf("unsupported kind %q (want %q)", t.Kind, KindTemplate)
	}
	if t.Metadata.Name == "" {
		return fmt.Errorf("metadata.name is required")
	}
	if t.Spec.Parameters == nil {
		return fmt.Errorf("spec.parameters is required")
	}
	if typ, _ := t.Spec.Parameters["type"].(string); typ != "object" {
		return fmt.Errorf(`spec.parameters.type must be "object"`)
	}
	for i, rule := range t.Spec.Files {
		if rule.Path == "" {
			return fmt.Errorf("spec.files[%d]: path is required", i)
		}
		// A rule with no condition either does nothing or means the author
		// forgot the condition; neither deserves to render.
		if rule.When == "" {
			return fmt.Errorf("spec.files[%d] (%s): when is required", i, rule.Path)
		}
		// Parsed here so a syntax error surfaces at load time rather than
		// partway through a render.
		if _, err := compileExpr(rule.When); err != nil {
			return fmt.Errorf("spec.files[%d] (%s): invalid when: %w", i, rule.Path, err)
		}
	}
	for i, dep := range t.Spec.Dependencies {
		if err := validateTemplateName(dep.Template); err != nil {
			return fmt.Errorf("spec.dependencies[%d]: %w", i, err)
		}
		if dep.Output == "" {
			return fmt.Errorf("spec.dependencies[%d] (%s): output is required", i, dep.Template)
		}
		// Parsed here so a syntax error surfaces at load time rather than
		// partway through a create, mirroring the spec.files check above.
		if dep.When != "" {
			if _, err := compileExpr(dep.When); err != nil {
				return fmt.Errorf("spec.dependencies[%d] (%s): invalid when: %w", i, dep.Template, err)
			}
		}
	}
	if t.Spec.Local != nil {
		if err := validateBindingCatalog("spec.local.fixtures", t.Spec.Local.Fixtures); err != nil {
			return err
		}
	}
	if t.Spec.GitOps != nil {
		if err := validateBindingCatalog("spec.gitops.bindingKinds", t.Spec.GitOps.BindingKinds); err != nil {
			return err
		}
	}
	return nil
}

func validateBindingCatalog(path string, bindings []string) error {
	seen := make(map[string]bool, len(bindings))
	for i, binding := range bindings {
		if !fixtureNamePattern.MatchString(binding) {
			return fmt.Errorf("%s[%d]: %q is not a valid binding name (lowercase letters, digits and dashes, starting with a letter or digit)", path, i, binding)
		}
		if seen[binding] {
			return fmt.Errorf("%s[%d]: %q is declared twice", path, i, binding)
		}
		seen[binding] = true
	}
	return nil
}

/** The in-memory registry tree, built from registry/** and serialized on demand. */

export type Attrs = Record<string, unknown>;

export interface Issue {
  /** error = the entity is dropped; warning = the entity is kept. */
  level: 'error' | 'warning';
  /** Source file the issue came from, relative to the repo root. */
  file: string;
  /** xid of the offending entity where one could be determined. */
  xid?: string;
  message: string;
}

export interface VersionEntity {
  versionid: string;
  attrs: Attrs;
  /** Parsed document, present only when the resource type has hasdocument: true. */
  document?: unknown;
  /** Original UTF-8 document bytes, retained for standards-compliant HTTP document retrieval. */
  documentText?: string;
  createdat: string;
  modifiedat: string;
  epoch: number;
}

export interface ResourceEntity {
  id: string;
  /** Plural name of the resource type, e.g. "schemas". */
  plural: string;
  singular: string;
  hasdocument: boolean;
  defaultVersionId: string;
  /** Insertion-ordered; the loader sorts versions naturally. */
  versions: Map<string, VersionEntity>;
  attrs: Attrs;
  /** Resource-level metadata exposed through the standard /meta entity. */
  createdat: string;
  modifiedat: string;
  epoch: number;
}

export interface GroupEntity {
  id: string;
  plural: string;
  singular: string;
  attrs: Attrs;
  createdat: string;
  modifiedat: string;
  epoch: number;
  /** resource plural -> resource id -> resource */
  resources: Map<string, Map<string, ResourceEntity>>;
}

export interface RegistryTree {
  registryid: string;
  name?: string;
  description?: string;
  createdat: string;
  modifiedat: string;
  epoch: number;
  /** group plural -> group id -> group */
  groups: Map<string, Map<string, GroupEntity>>;
  issues: Issue[];
}

/**
 * Entity tree -> xRegistry JSON.
 *
 * Two views, per the core spec:
 *   API view  — absolute self URLs, <COLLECTION>url and <COLLECTION>count present,
 *               a Resource carries its default Version's attributes.
 *   doc view  — relative references, collection url/count omitted, and the
 *               default Version's attributes NOT repeated on the Resource.
 *
 * Doc-view references are emitted as root-relative xids. The spec requires
 * "relative references" without fixing a form; the xid is the one form that is
 * unambiguous and round-trips through /export.
 */

import type { GroupEntity, RegistryTree, ResourceEntity, VersionEntity } from './types.js';
import { SPEC_VERSION } from './model.js';
import { shouldInline, type InlineSpec } from './query.js';

type Json = Record<string, unknown>;

export interface SerializeOptions {
  baseUrl: string;
  /** Document view (?doc). */
  doc: boolean;
  inline: InlineSpec;
  /** Inlined only when requested. */
  model?: Json;
  capabilities?: Json;
}

export const defaultOptions = (baseUrl: string): SerializeOptions => ({
  baseUrl,
  doc: false,
  inline: { wildcard: false, paths: [] },
});

/** A reference to another entity: absolute in API view, xid in doc view. */
function ref(opts: SerializeOptions, xid: string): string {
  return opts.doc ? xid : `${opts.baseUrl}${xid === '/' ? '/' : xid}`;
}

/**
 * Emit the three-attribute collection pattern. In doc view url and count are
 * omitted, since the spec makes them optional there and they are duplicate data.
 */
function collection(
  target: Json,
  plural: string,
  opts: SerializeOptions,
  parentXid: string,
  path: string[],
  members: Json | undefined,
  count: number,
): void {
  const xid = `${parentXid === '/' ? '' : parentXid}/${plural}`;
  if (!opts.doc) {
    target[`${plural}url`] = ref(opts, xid);
    target[`${plural}count`] = count;
  }
  if (members !== undefined && shouldInline(opts.inline, path)) {
    target[plural] = members;
  }
}

function resourceXid(group: GroupEntity, resource: ResourceEntity): string {
  return `/${group.plural}/${group.id}/${resource.plural}/${resource.id}`;
}

function versionXid(group: GroupEntity, resource: ResourceEntity, versionid: string): string {
  return `${resourceXid(group, resource)}/versions/${versionid}`;
}

function metaXid(group: GroupEntity, resource: ResourceEntity): string {
  return `${resourceXid(group, resource)}/meta`;
}

export function serializeVersion(
  group: GroupEntity,
  resource: ResourceEntity,
  version: VersionEntity,
  opts: SerializeOptions,
  path: string[],
): Json {
  const xid = versionXid(group, resource, version.versionid);
  const out: Json = {
    [`${resource.singular}id`]: resource.id,
    versionid: version.versionid,
    self: ref(opts, xid),
    xid,
    epoch: version.epoch,
    isdefault: version.versionid === resource.defaultVersionId,
    createdat: version.createdat,
    modifiedat: version.modifiedat,
    ...version.attrs,
  };
  attachDocument(out, resource, version, opts, path);
  return out;
}

/**
 * For hasdocument resources the document is inlined as <singular> only when
 * requested. Direct document retrieval is handled by the HTTP binding.
 */
function attachDocument(
  target: Json,
  resource: ResourceEntity,
  version: VersionEntity,
  opts: SerializeOptions,
  path: string[],
): void {
  if (!resource.hasdocument || version.document === undefined) return;
  if (shouldInline(opts.inline, [...path, resource.singular])) {
    target[resource.singular] = version.document;
  }
}

export function serializeResource(
  group: GroupEntity,
  resource: ResourceEntity,
  opts: SerializeOptions,
  path: string[],
): Json {
  const xid = resourceXid(group, resource);
  const dflt = resource.versions.get(resource.defaultVersionId)!;

  const out: Json = { [`${resource.singular}id`]: resource.id };

  if (opts.doc) {
    // Duplicate data removed: no default-Version attributes on the Resource.
    out['self'] = ref(opts, xid);
    out['xid'] = xid;
    Object.assign(out, resource.attrs);
  } else {
    Object.assign(out, {
      versionid: dflt.versionid,
      self: ref(opts, xid),
      xid,
      epoch: dflt.epoch,
      isdefault: true,
      createdat: dflt.createdat,
      modifiedat: dflt.modifiedat,
      ...resource.attrs,
      ...dflt.attrs,
      metaurl: ref(opts, metaXid(group, resource)),
    });
    attachDocument(out, resource, dflt, opts, path);
  }

  const versionsPath = [...path, 'versions'];
  const members: Json = {};
  for (const [vid, version] of resource.versions) {
    members[vid] = serializeVersion(group, resource, version, opts, versionsPath);
  }
  collection(out, 'versions', opts, xid, versionsPath, members, resource.versions.size);
  return out;
}

/** Serialize the Resource-level metadata entity exposed at /meta. */
export function serializeMeta(group: GroupEntity, resource: ResourceEntity, opts: SerializeOptions): Json {
  const xid = metaXid(group, resource);
  return {
    [`${resource.singular}id`]: resource.id,
    self: ref(opts, xid),
    xid,
    epoch: resource.epoch,
    createdat: resource.createdat,
    modifiedat: resource.modifiedat,
    ...resource.attrs,
    defaultversionid: resource.defaultVersionId,
    defaultversionurl: ref(opts, versionXid(group, resource, resource.defaultVersionId)),
  };
}

export function serializeGroup(group: GroupEntity, opts: SerializeOptions, path: string[]): Json {
  const xid = `/${group.plural}/${group.id}`;
  const out: Json = {
    [`${group.singular}id`]: group.id,
    self: ref(opts, xid),
    xid,
    epoch: group.epoch,
    createdat: group.createdat,
    modifiedat: group.modifiedat,
    ...group.attrs,
  };

  for (const [plural, resources] of group.resources) {
    const resourcePath = [...path, plural];
    const members: Json = {};
    for (const [rid, resource] of resources) {
      members[rid] = serializeResource(group, resource, opts, resourcePath);
    }
    collection(out, plural, opts, xid, resourcePath, members, resources.size);
  }
  return out;
}

/** Serialize one collection of groups. */
export function serializeGroupCollection(
  groups: Map<string, GroupEntity>,
  opts: SerializeOptions,
  path: string[],
): Json {
  const out: Json = {};
  for (const [gid, group] of groups) {
    out[gid] = serializeGroup(group, opts, path);
  }
  return out;
}

export function serializeRegistry(tree: RegistryTree, opts: SerializeOptions): Json {
  const out: Json = {
    specversion: SPEC_VERSION,
    registryid: tree.registryid,
    self: ref(opts, '/'),
    xid: '/',
    epoch: tree.epoch,
    createdat: tree.createdat,
    modifiedat: tree.modifiedat,
  };
  if (tree.name !== undefined) out['name'] = tree.name;
  if (tree.description !== undefined) out['description'] = tree.description;

  if (opts.capabilities && shouldInline(opts.inline, ['capabilities'])) {
    out['capabilities'] = opts.capabilities;
  }
  if (opts.model && shouldInline(opts.inline, ['model'])) {
    out['model'] = opts.model;
  }
  for (const [plural, groups] of tree.groups) {
    const path = [plural];
    collection(out, plural, opts, '/', path, serializeGroupCollection(groups, opts, path), groups.size);
  }
  return out;
}

