const schemagroups = new Map<string, GroupEntity>();
for (const { doc, file, mtime } of loaded.schemagroups) {
  const gid = doc.schemagroupid;
  if (schemagroups.has(gid)) {
    issues.push({ level: 'error', file, xid: `/schemagroups/${gid}`, message: `duplicate schemagroupid "${gid}"` });
    continue;
  }
  schemagroups.set(gid, {
    id: gid,
    plural: 'schemagroups',
    singular: 'schemagroup',
    attrs: defined({ ...commonAttrs(doc), format: doc.format }),
    ...timestamps(doc, mtime),
    resources: new Map([['schemas', new Map()]]),
  });
}

for (const loadedSchema of loaded.schemas) {
  const { doc, file, schemagroupid, schemaid, versions } = loadedSchema;
  const group = schemagroups.get(schemagroupid);
  if (!group) continue; // its group failed to load; the error is already recorded
  const rxid = `/schemagroups/${schemagroupid}/schemas/${schemaid}`;

  // Group-level constraint from schema/model.json: schemas.format equals format.
  const groupFormat = group.attrs['format'];
  if (typeof groupFormat === 'string' && groupFormat !== doc.format) {
    issues.push({
      level: 'error',
      file,
      xid: rxid,
      message: `format "${doc.format}" does not equal its group's format "${groupFormat}"`,
    });
    continue;
  }

  const versionMap = new Map<string, VersionEntity>();
  for (const v of versions) {
    versionMap.set(v.versionid, {
      versionid: v.versionid,
      // format is matchversions: true, so every version carries the same value.
      attrs: defined({ format: doc.format, contenttype: doc.contenttype }),
      document: v.document,
      documentText: v.documentText,
      createdat: doc.createdat ?? v.mtime,
      modifiedat: doc.modifiedat ?? v.mtime,
      epoch: doc.epoch ?? 1,
    });
  }

  const lastVersion = versions[versions.length - 1];
  const defaultVersionId = doc.defaultversionid ?? lastVersion!.versionid;
  if (!versionMap.has(defaultVersionId)) {
    issues.push({
      level: 'error',
      file,
      xid: rxid,
      message: `defaultversionid "${defaultVersionId}" is not one of the versions on disk`,
    });
    continue;
  }

  group.resources.get('schemas')!.set(schemaid, {
    id: schemaid,
    plural: 'schemas',
    singular: 'schema',
    hasdocument: true,
    defaultVersionId,
    versions: versionMap,
    attrs: defined({ ...commonAttrs(doc), compatibility: doc.compatibility }),
    ...timestamps(doc, loadedSchema.mtime),
  });
}
groups.set('schemagroups', schemagroups);

// ---------------------------------------------------------------- endpoints
const endpoints = new Map<string, GroupEntity>();
const channelledMessagegroups = new Set<string>();
for (const { doc, file, mtime } of loaded.endpoints) {
  const gid = doc.endpointid;
  const gxid = `/endpoints/${gid}`;
  if (endpoints.has(gid)) {
    issues.push({ level: 'error', file, xid: gxid, message: `duplicate endpointid "${gid}"` });
    continue;
  }
  for (const ref of doc.messagegroups) {
    const target = ref.replace(/^\/messagegroups\//, '');
    if (!messagegroups.has(target)) {
      issues.push({
        level: 'warning',
        file,
        xid: gxid,
        message: `messagegroups reference "${ref}" does not resolve in this registry`,
      });
    } else {
      channelledMessagegroups.add(target);
    }
  }
  endpoints.set(gid, {
    id: gid,
    plural: 'endpoints',
    singular: 'endpoint',
    attrs: defined({
      ...commonAttrs(doc),
      usage: doc.usage,
      channel: doc.channel,
      envelope: doc.envelope,
      envelopeoptions: doc.envelopeoptions,
      protocol: doc.protocol,
      protocoloptions: doc.protocoloptions,
      messagegroups: doc.messagegroups,
    }),
    ...timestamps(doc, mtime),
    // endpoints import the messages resource type but we do not inline
    // per-endpoint message overrides; they reference groups instead.
    resources: new Map([['messages', new Map()]]),
  });
}
groups.set('endpoints', endpoints);

// A Message has no channel attribute in the xRegistry model. The native
// association is Endpoint.channel + Endpoint.messagegroups, so every local
// message group must be carried by at least one channelled endpoint.
for (const [id] of messagegroups) {
  if (!channelledMessagegroups.has(id)) {
    issues.push({
      level: 'error',
      file: `messagegroups/${id}.yaml`,
      xid: `/messagegroups/${id}`,
      message: 'message group is not referenced by any endpoint channel',
    });
  }
}

// ------------------------------------- cross-reference: message -> schema
for (const group of messagegroups.values()) {
  for (const message of group.resources.get('messages')!.values()) {
    const xid = message.versions.get(message.defaultVersionId)!.attrs['dataschemaxid'];
    if (typeof xid !== 'string') continue;
    const m = /^\/schemagroups\/([^/]+)\/schemas\/([^/]+)$/.exec(xid);
    const resolved = m && schemagroups.get(m[1]!)?.resources.get('schemas')?.get(m[2]!);
    if (!resolved) {
      issues.push({
        level: 'warning',
        xid: `/messagegroups/${group.id}/messages/${message.id}`,
        file: `messagegroups/${group.id}.yaml`,
        message: `dataschemaxid "${xid}" does not resolve to a schema in this registry`,
      });
    }
  }
}

const allTimes = [...messagegroups.values(), ...schemagroups.values(), ...endpoints.values()].map(
  (g) => g.modifiedat,
);
const modifiedat = allTimes.length ? allTimes.sort().at(-1)! : new Date(0).toISOString();

return {
  registryid: loaded.registry.registryid,
  name: loaded.registry.name,
  description: loaded.registry.description,
  createdat: loaded.registry.createdat ?? modifiedat,
  modifiedat,
  epoch: loaded.registry.epoch ?? 1,
  groups,

package main

import (
	"regexp"
	"strings"
	"testing"

	"github.com/spf13/cobra"
)

// These tests walk the whole command tree and enforce the writing rules in
// AGENTS.md, so a new command cannot silently re-introduce a wall of help
// text or a malformed Use string.

// maxLongWords is the hard ceiling for a Long description. AGENTS.md targets
// 150 words; this ceiling is looser so the test does not fight legitimate
// detail, but a wall of text trips it.
const maxLongWords = 220

// usePattern enforces: lowercase command name, positional args as <name>,
// optionals as [name], variadic as [name...].
var usePattern = regexp.MustCompile(`^[a-z][a-z0-9-]*( <[a-z][a-z0-9-]*>)*( \[[a-z][a-z0-9-]*(\.\.\.)?\])*$`)

func walkCommands(cmd *cobra.Command, out []*cobra.Command) []*cobra.Command {
	out = append(out, cmd)
	for _, c := range cmd.Commands() {
		out = walkCommands(c, out)
	}
	return out
}

func TestHelpTextLongLength(t *testing.T) {
	for _, cmd := range walkCommands(rootCmd, nil) {
		words := len(strings.Fields(cmd.Long))
		if words > maxLongWords {
			t.Errorf("%s: Long is %d words (max %d) — move rationale to docs/, keep --help to usage",
				cmd.CommandPath(), words, maxLongWords)
		}
	}
}

func TestHelpTextShortStyle(t *testing.T) {
	for _, cmd := range walkCommands(rootCmd, nil) {
		if cmd.Short == "" {
			t.Errorf("%s: Short is empty", cmd.CommandPath())
			continue
		}
		if strings.HasSuffix(cmd.Short, ".") {
			t.Errorf("%s: Short ends with a period (fragments only, per AGENTS.md)", cmd.CommandPath())
		}
		if strings.Contains(cmd.Short, "\n") {
			t.Errorf("%s: Short contains a newline", cmd.CommandPath())
		}
	}
}

func TestHelpTextUsePattern(t *testing.T) {
	for _, cmd := range walkCommands(rootCmd, nil) {
		// cmd.Use is the first line only; cobra may append aliases on later
		// lines, which the pattern does not cover.
		use, _, _ := strings.Cut(cmd.Use, "\n")
		if !usePattern.MatchString(use) {
			t.Errorf("%s: Use %q does not match 'cmd <arg> [opt]...' conventions", cmd.CommandPath(), cmd.Use)
		}
		if strings.Contains(use, "[<") || strings.Contains(use, ">]") {
			t.Errorf("%s: Use %q wraps optional markers around angle brackets; write [name] not [<name>]",
				cmd.CommandPath(), cmd.Use)
		}
	}
}

func TestHelpTextCommandVerbsAreDocumented(t *testing.T) {
	// The verb set documented in AGENTS.md under "Command verbs". A command
	// introducing a verb outside this set fails here; the fix is either to
	// use an existing verb or to document the new one in AGENTS.md first.
	documentedVerbs := map[string]bool{
		"list": true, "show": true, "status": true, "diff": true, "inspect": true, "render": true,
		"create": true, "add": true, "update": true, "init": true,
		"publish": true, "pin": true, "promote": true, "sync": true, "use": true,
	}
	// Nouns, command groups, and standalone commands that are not verbs and
	// so are not governed by the AGENTS.md verb table.
	notVerbs := map[string]bool{
		"intropy": true, "int": true, "template": true,
		"deploy": true, "manifests": true, "release": true, "sys": true,
		"version": true, "dashboard": true,
		// Command group for customer contexts; its subcommands (use, list,
		// show) are documented verbs.
		"context": true,
		// Hidden stubs kept so old muscle memory gets a pointer, not an
		// unknown-command error; see int_describe.go and int_local.go.
		"describe": true, "local": true,
		// Cobra's built-ins and the shell names it registers under
		// 'completion'; none are authored verbs.
		"help": true, "completion": true,
		"bash": true, "zsh": true, "fish": true, "powershell": true,
	}
	for _, cmd := range walkCommands(rootCmd, nil) {
		name := cmd.Name()
		if notVerbs[name] || documentedVerbs[name] {
			continue
		}
		t.Errorf("%s: verb %q is not documented in AGENTS.md 'Command verbs' — use an existing verb or document the new one there",
			cmd.CommandPath(), name)
	}
}

func TestHelpTextSharedFlagsUseConstants(t *testing.T) {
	// The descriptions shared flags must carry, from flagtext.go. A command
	// that re-introduces a hand-written variant fails here.
	want := map[string]string{
		"output":        flagUsageOutput,
		"gitops-repo":   flagUsageGitopsRepo,
		"argocd-server": flagUsageArgocd,
		"domain":        flagUsageDomain,
		"system":        flagUsageSystem,
	}
	// Flags whose meaning legitimately differs on one command get their own
	// constant in flagtext.go; allow those here.
	allowed := map[string]map[string]bool{
		"output": {flagUsageOutput: true, flagUsageOutputJSONOnly: true},
		"domain": {flagUsageDomain: true, flagUsageManifestDomain: true},
		"system": {flagUsageSystem: true, flagUsageManifestSystem: true},
	}
	for _, cmd := range walkCommands(rootCmd, nil) {
		for name, desc := range want {
			f := cmd.Flags().Lookup(name)
			if f == nil {
				continue
			}
			if ok := allowed[name][f.Usage]; !ok && f.Usage != desc {
				t.Errorf("%s: --%s description is %q, want a shared constant from flagtext.go (e.g. %q)",
					cmd.CommandPath(), name, f.Usage, desc)
			}
		}
	}
}

package template

import (
	"path/filepath"
	"testing"
)

func wiringEntry(values map[string]any) ScaffoldEntry {
	return ScaffoldEntry{Path: "order-extractor", Scaffold: Scaffold{Values: values}}
}

func TestRecordValue(t *testing.T) {
	recordPath := filepath.ToSlash(filepath.Join("order-extractor", filepath.FromSlash(ScaffoldRelPath)))

	t.Run("missing, mistyped, and empty name the record", func(t *testing.T) {
		cases := []struct {
			values  map[string]any
			wantErr string
		}{
			{map[string]any{}, recordPath + ": values.topic is missing"},
			{map[string]any{"topic": float64(7)}, recordPath + ": values.topic has type float64, expected string"},
			{map[string]any{"topic": ""}, recordPath + ": values.topic is empty"},
		}
		for _, tc := range cases {
			if _, err := RecordValue(wiringEntry(tc.values), KeyTopic); err == nil || filepath.ToSlash(err.Error()) != tc.wantErr {
				t.Errorf("RecordValue(%v) err = %v, want %q", tc.values, err, tc.wantErr)
			}
		}
	})

	t.Run("present value returns", func(t *testing.T) {
		got, err := RecordValue(wiringEntry(map[string]any{"topic": "orders"}), KeyTopic)
		if err != nil || got != "orders" {
			t.Errorf("RecordValue = %q, %v; want orders, nil", got, err)
		}
	})
}

func TestRecordValueDefault(t *testing.T) {
	t.Run("missing falls back", func(t *testing.T) {
		got, err := RecordValueDefault(wiringEntry(map[string]any{}), KeyPubsub, DefaultPubsub)
		if err != nil || got != DefaultPubsub {
			t.Errorf("RecordValueDefault = %q, %v; want %q, nil", got, err, DefaultPubsub)
		}
	})

	t.Run("present but mistyped or empty is an error, not the fallback", func(t *testing.T) {
		for _, values := range []map[string]any{{"pubsub": 7}, {"pubsub": ""}} {
			if _, err := RecordValueDefault(wiringEntry(values), KeyPubsub, DefaultPubsub); err == nil {
				t.Errorf("RecordValueDefault(%v) = nil error, want a record error", values)
			}
		}
	})
}

func TestSoftValue(t *testing.T) {
	cases := []struct {
		values map[string]any
		want   string
		ok     bool
	}{
		{map[string]any{"topic": "orders"}, "orders", true},
		{map[string]any{}, "", false},
		{map[string]any{"topic": ""}, "", false},
		{map[string]any{"topic": 7}, "", false},
	}
	for _, tc := range cases {
		got, ok := SoftValue(tc.values, KeyTopic)
		if got != tc.want || ok != tc.ok {
			t.Errorf("SoftValue(%v) = %q, %v; want %q, %v", tc.values, got, ok, tc.want, tc.ok)
		}
	}
}

