package xregistry

// The served subset of the xRegistry 1.0-rc2x document model, decoded from
// GET /export. The registry is API-only and read-only (the service refuses
// filtering, inlining, and pagination), so the whole model arrives in one
// document and all resolution joins happen in memory against it.
//
// /export is the doc view: references are root-relative xids, collection
// urls and counts are absent, and for hasdocument resources the default
// Version's attributes are NOT repeated on the Resource. For messages —
// maxversions: 1 — every attribute therefore lives on the single implicit
// version, never on the message resource itself. Schemas, by contrast, are
// multi-version resources whose versions each carry isdefault.

// Export is the whole registry document from GET /export. The three
// collections are top-level group collections; an absent collection decodes
// as an empty map, so a caller never nil-checks.
type Export struct {
	SpecVersion   string                  `json:"specversion"`
	RegistryID    string                  `json:"registryid"`
	MessageGroups map[string]MessageGroup `json:"messagegroups"`
	Endpoints     map[string]Endpoint     `json:"endpoints"`
	SchemaGroups  map[string]SchemaGroup  `json:"schemagroups"`
}

// MessageGroup is one xRegistry message group carrying its message
// collection. The registry guarantees every published group is referenced
// by at least one channelled endpoint.
type MessageGroup struct {
	ID       string             `json:"messagegroupid"`
	Name     string             `json:"name,omitempty"`
	Messages map[string]Message `json:"messages"`
}

// Message is one message definition in the doc view. Definition attributes
// (envelope metadata, dataschemaxid) live on the single implicit version
// under Versions, not here — this is the doc view, which does not repeat
// the default version's attributes on the resource.
type Message struct {
	ID       string                     `json:"messageid"`
	Versions map[string]MessageVersion  `json:"versions"`

	// Definition fields are set only on per-entity (API view) reads, where
	// the default version's attributes ARE repeated on the resource. Code
	// reading a message goes through defaultMessage() so the two views
	// resolve identically.
	Envelope         string                   `json:"envelope,omitempty"`
	EnvelopeMetadata map[string]CEAttribute   `json:"envelopemetadata,omitempty"`
	DataSchemaFormat string                   `json:"dataschemaformat,omitempty"`
	DataSchemaXID    string                   `json:"dataschemaxid,omitempty"`
	DataContentType  string                   `json:"datacontenttype,omitempty"`
}

// MessageVersion is one version of a message definition. Messages have
// exactly one implicit version (versionid "1") carrying the definition.
type MessageVersion struct {
	VersionID        string                 `json:"versionid"`
	IsDefault        bool                   `json:"isdefault"`
	Envelope         string                 `json:"envelope,omitempty"`
	EnvelopeMetadata map[string]CEAttribute `json:"envelopemetadata,omitempty"`
	DataSchemaFormat string                 `json:"dataschemaformat,omitempty"`
	DataSchemaXID    string                 `json:"dataschemaxid,omitempty"`
	DataContentType  string                 `json:"datacontenttype,omitempty"`
}

// CEAttribute is one envelope metadata attribute. The registry constrains
// some attributes with a constant value; a message's CloudEvents type is
// the value of its `type` attribute.
type CEAttribute struct {
	Value       any    `json:"value"`
	Type        string `json:"type,omitempty"`
	Required    bool   `json:"required,omitempty"`
	Description string `json:"description,omitempty"`
}

// Endpoint is one registry endpoint: a role, the channel the endpoint
// speaks on, and the message groups allowed on it. Channel is
// <pubsub>/<topic>; the split helper in resolve.go owns the format.
type Endpoint struct {
	ID            string   `json:"endpointid"`
	Name          string   `json:"name,omitempty"`
	Usage         []string `json:"usage,omitempty"`
	Channel       string   `json:"channel,omitempty"`
	MessageGroups []string `json:"messagegroups,omitempty"`
}

// SchemaGroup is one schema group carrying schema resources.
type SchemaGroup struct {
	ID      string           `json:"schemagroupid"`
	Name    string           `json:"name,omitempty"`
	Schemas map[string]Schema `json:"schemas"`
}

// Schema is one schema resource. Versions carry isdefault; the default
// version URL is the immutable pin a CloudEvent dataschema references.
type Schema struct {
	ID       string          `json:"schemaid"`
	Format   string          `json:"format,omitempty"`
	Versions map[string]Version `json:"versions"`
}

// Version is one immutable schema version. XID is root-relative; the
// pinned URL is the base URL joined with it.
type Version struct {
	VersionID string `json:"versionid"`
	XID       string `json:"xid,omitempty"`
	IsDefault bool   `json:"isdefault"`
}

// Package xregistry is a read-only client for the Intropy xRegistry
// service: message, endpoint, and schema discovery over GET /export, plus
// in-memory resolution of a message reference into the wiring a component
// needs to subscribe to it.
//
// It shares a name and nothing else with internal/registry, the OCI
// registry client — different protocol, different base URL, different
// failure model. The two packages are unrelated and must not borrow each
// other's types; a rename of one is not a rename of the other.
//
// xRegistry has no message-to-channel field: the association is
// Endpoint.messagegroups (the groups allowed on an endpoint) plus
// Endpoint.channel, and the resolution join in resolve.go walks it. The
// registry declares filtering, inlining, and pagination out of scope, so
// the client sends only GET /export and the plain entity paths — no query
// params it did not see advertised.
package xregistry

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// Client speaks to one read-only xRegistry service. Construct with New;
// methods take a context first and never retry internally — the caller
// owns timeouts and the retry policy.
type Client struct {
	base      *url.URL
	httpClient *http.Client
	userAgent string
}

type options struct {
	httpClient *http.Client
	userAgent  string
}

// Option customises New.
type Option func(*options)

// WithHTTPClient replaces the default client. Tests inject an httptest
// transport here.
func WithHTTPClient(c *http.Client) Option {
	return func(o *options) { o.httpClient = c }
}

// WithUserAgent sets the User-Agent header on every request.
func WithUserAgent(ua string) Option {
	return func(o *options) { o.userAgent = ua }
}

// New builds a Client for the service at baseURL. The base URL must parse
// and be absolute: a relative base would make every request path a guess.
func New(baseURL string, opts ...Option) (*Client, error) {
	u, err := url.Parse(strings.TrimSuffix(baseURL, "/"))
	if err != nil {
		return nil, fmt.Errorf("parse xRegistry base URL %q: %w", baseURL, err)
	}
	if !u.IsAbs() {
		return nil, fmt.Errorf("xRegistry base URL %q is not absolute", baseURL)
	}
	o := options{httpClient: http.DefaultClient}
	for _, opt := range opts {
		opt(&o)
	}
	return &Client{base: u, httpClient: o.httpClient, userAgent: o.userAgent}, nil
}

// BaseURL reports the service root the client was built against, without
// a trailing slash.
func (c *Client) BaseURL() string { return c.base.String() }

// get issues one GET and decodes the JSON body into out. Error bodies are
// the xRegistry error document; both the transport error and the body are
// surfaced so the caller can front-load what failed.
func (c *Client) get(ctx context.Context, path string, out any) error {
	u := c.base.JoinPath(path)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return fmt.Errorf("build request for %s: %w", path, err)
	}
	req.Header.Set("Accept", "application/json")
	if c.userAgent != "" {
		req.Header.Set("User-Agent", c.userAgent)
	}
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("GET %s: %w", u.String(), err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBodyBytes))
	if err != nil {
		return fmt.Errorf("read %s: %w", u.String(), err)
	}
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("GET %s: registry returned %s: %s", u.String(), resp.Status, errorBody(body))
	}
	if err := json.Unmarshal(body, out); err != nil {
		return fmt.Errorf("parse %s: %w", u.String(), err)
	}
	return nil
}

// maxBodyBytes bounds a response read. The export of a registry that grew
// past this size is itself an operational problem — silently truncating a
// resolution input would be worse than failing loudly.
const maxBodyBytes = 64 << 20

// errorBody condenses an xRegistry error document ({code, detail, status})
// into one line; a body that does not parse is shown truncated as-is.
func errorBody(body []byte) string {
	var doc struct {
		Code   string `json:"code"`
		Detail string `json:"detail"`
	}
	if err := json.Unmarshal(body, &doc); err == nil && doc.Code != "" {
		if doc.Detail != "" {
			return doc.Code + ": " + doc.Detail
		}
		return doc.Code
	}
	const maxLen = 200
	s := string(body)
	if len(s) > maxLen {
		s = s[:maxLen] + "…"
	}
	return s
}

// Export fetches the complete registry document. One call, no walk: the
// service guarantees /export is byte-identical to the entity paths, and
// per-entity fetches exist only for single-message freshness (Message).
func (c *Client) Export(ctx context.Context) (*Export, error) {
	var doc Export
	if err := c.get(ctx, "/export", &doc); err != nil {
		return nil, fmt.Errorf("fetch xRegistry export: %w", err)
	}
	return &doc, nil
}

// Message fetches one message's definition via its entity path — the
// freshness read for single-message display, not required for resolution.
// The response is the API view: the default version's attributes are
// repeated on the resource, so the returned Message carries them directly.
func (c *Client) Message(ctx context.Context, groupID, messageID string) (*Message, error) {
	var m Message
	path := fmt.Sprintf("/messagegroups/%s/messages/%s", url.PathEscape(groupID), url.PathEscape(messageID))
	if err := c.get(ctx, path, &m); err != nil {
		return nil, fmt.Errorf("fetch message %s in group %s: %w", messageID, groupID, err)
	}
	return &m, nil
}

// defaultMessage resolves a message's definition attributes, whichever
// view produced the struct: the export's doc view keeps attributes on the
// single implicit version, the entity path repeats them on the resource.
func (m *Message) defaultMessage() *MessageVersion {
	if len(m.Versions) == 0 {
		// API view with the attributes already on the resource: the
		// version map is empty but the definition is present.
		if m.DataSchemaXID != "" || m.EnvelopeMetadata != nil || m.Envelope != "" {
			return &MessageVersion{
				VersionID:        "1",
				IsDefault:        true,
				Envelope:         m.Envelope,
				EnvelopeMetadata: m.EnvelopeMetadata,
				DataSchemaFormat: m.DataSchemaFormat,
				DataSchemaXID:    m.DataSchemaXID,
				DataContentType:  m.DataContentType,
			}
		}
		return nil
	}
	var dflt *MessageVersion
	for i := range m.Versions {
		v := &m.Versions[i]
		if v.IsDefault {
			return v
		}
		if dflt == nil {
			dflt = v
		}
	}
	// Versions without isdefault markers: fall back to the first — the
	// single implicit version every message carries.
	return dflt
}

package xregistry

import (
	"fmt"
	"sort"
	"strings"
)

// Channel is one producing channel: the pub/sub component and topic an
// event flows through, as split from the endpoint's <pubsub>/<topic>
// channel string.
type Channel struct {
	Pubsub   string `json:"pubsub"`
	Topic    string `json:"topic"`
	Endpoint string `json:"endpoint,omitempty"`
}

// ResolvedMessage is the wiring --subscribe writes into a scaffold record:
// the message identity, its CloudEvents type, the channels the message can
// arrive on, and the schema pin.
type ResolvedMessage struct {
	// Message is the message id, which for these registries doubles as the
	// CloudEvents type — the registry constrains envelopemetadata.type to
	// the same dotted name. Type carries the envelope value verbatim; the
	// two are distinct fields so a registry that ever diverges them stays
	// representable.
	Message string `json:"message"`
	Type    string `json:"type,omitempty"`
	Group   string `json:"group"`

	// Channels is the set of producer endpoints' channels for the message's
	// group, split and sorted. Exactly one is the subscribe channel; more
	// is AmbiguousProducerError, none is NoProducerError.
	Channels []Channel `json:"channels,omitempty"`

	// DataSchema is the logical schema xid from the message definition;
	// DataSchemaURL pins the schema's default version — an immutable URL —
	// at subscribe time.
	DataSchema    string `json:"dataschema,omitempty"`
	DataSchemaURL string `json:"dataschemaurl,omitempty"`

	Envelope string `json:"envelope,omitempty"`
}

// ResolveMessage resolves one message reference — a bare message id or a
// full /messagegroups/<gid>/messages/<mid> xid — against the export
// document into subscription wiring. All joins are in memory: nothing but
// the export is fetched.
//
// The resolution the caller cannot do without: message → group → producer
// endpoints → channel split, plus dataschemaxid → default version URL.
func ResolveMessage(doc *Export, ref string) (*ResolvedMessage, error) {
	msg, group, err := findMessage(doc, ref)
	if err != nil {
		return nil, err
	}
	dflt := msg.defaultMessage()
	if dflt == nil {
		return nil, &NoDefaultVersionError{Ref: ref, Group: group.ID}
	}

	res := &ResolvedMessage{
		Message: msg.ID,
		Group:   group.ID,
		Envelope: dflt.Envelope,
	}
	if attr, ok := dflt.EnvelopeMetadata["type"]; ok {
		if s, ok := attr.Value.(string); ok {
			res.Type = s
		}
	}
	res.DataSchema = dflt.DataSchemaXID
	if res.DataSchema != "" {
		u, err := schemaVersionURL(doc, res.DataSchema)
		if err != nil {
			return nil, err
		}
		res.DataSchemaURL = u
	}

	channels, err := producerChannels(doc, group.ID)
	if err != nil {
		return nil, err
	}
	res.Channels = channels
	return res, nil
}

// SubscribeChannel picks the one channel of a resolved message. The choice
// is the caller's only when several producers carry the group on different
// channels — the interactive pick list and the --no-input error both
// consume the full Channels list, so it is kept there.
func (r *ResolvedMessage) SubscribeChannel() (Channel, error) {
	switch len(r.Channels) {
	case 0:
		return Channel{}, &NoProducerError{Group: r.Group}
	case 1:
		return r.Channels[0], nil
	default:
		return Channel{}, &AmbiguousProducerError{Ref: r.Message, Channels: r.Channels}
	}
}

// findMessage locates a message by reference. A bare id is matched across
// groups and must name exactly one message — two groups reusing one id is
// ambiguity the reference alone cannot resolve.
func findMessage(doc *Export, ref string) (*Message, *MessageGroup, error) {
	if ref == "" {
		return nil, nil, fmt.Errorf("message reference is empty")
	}
	if xid, ok := strings.CutPrefix(ref, "/messagegroups/"); ok {
		gid, mid, ok := strings.Cut(xid, "/messages/")
		if !ok || gid == "" || mid == "" {
			return nil, nil, fmt.Errorf("message reference %q is not a message id or /messagegroups/<gid>/messages/<mid> xid", ref)
		}
		g, ok := doc.MessageGroups[gid]
		if !ok {
			return nil, nil, &MessageNotFoundError{Ref: ref}
		}
		m, ok := g.Messages[mid]
		if !ok {
			return nil, nil, &MessageNotFoundError{Ref: ref}
		}
		return &m, &g, nil
	}

	var found *Message
	var group *MessageGroup
	for i := range doc.MessageGroups {
		g := doc.MessageGroups[i]
		if m, ok := g.Messages[ref]; ok {
			if found != nil {
				xids := messageGroupXIDs(doc, ref)
				return nil, nil, fmt.Errorf("message reference %q is ambiguous: declared in groups %s", ref, strings.Join(xids, ", "))
			}
			mCopy, gCopy := m, g
			found, group = &mCopy, &gCopy
		}
	}
	if found == nil {
		return nil, nil, &MessageNotFoundError{Ref: ref}
	}
	return found, group, nil
}

// messageGroupXIDs names the groups carrying ref, for the ambiguity error.
func messageGroupXIDs(doc *Export, ref string) []string {
	var out []string
	for _, g := range doc.MessageGroups {
		if _, ok := g.Messages[ref]; ok {
			out = append(out, "/messagegroups/"+g.ID)
		}
	}
	sort.Strings(out)
	return out
}

// producerChannels joins the group to its producer endpoints and splits
// each channel. Endpoints whose usage omits "producer" are subscriptions
// and consumers, never the resolution answer.
func producerChannels(doc *Export, groupID string) ([]Channel, error) {
	want := "/messagegroups/" + groupID
	var channels []Channel
	for _, e := range doc.Endpoints {
		if !slicesContain(e.Usage, "producer") {
			continue
		}
		if !slicesContain(e.MessageGroups, want) {
			continue
		}
		pubsub, topic, err := SplitChannel(e.Channel)
		if err != nil {
			return nil, &ChannelFormatError{Endpoint: e.ID, Channel: e.Channel, err: err}
		}
		channels = append(channels, Channel{Pubsub: pubsub, Topic: topic, Endpoint: e.ID})
	}
	sort.Slice(channels, func(i, j int) bool {
		if channels[i].Pubsub != channels[j].Pubsub {
			return channels[i].Pubsub < channels[j].Pubsub
		}
		return channels[i].Topic < channels[j].Topic
	})
	return channels, nil
}

// SplitChannel splits an endpoint channel into its pub/sub component and
// topic halves. The format belongs to the registry's conformance suite;
// this validates and fails naming the endpoint rather than accepting a
// half-parsed channel.
func SplitChannel(channel string) (pubsub, topic string, err error) {
	pubsub, topic, ok := strings.Cut(channel, "/")
	if !ok || strings.TrimSpace(pubsub) == "" || strings.TrimSpace(topic) == "" {
		return "", "", fmt.Errorf("channel %q is not <pubsub>/<topic>", channel)
	}
	return pubsub, topic, nil
}

// schemaVersionURL pins a logical schema xid to its default version URL —
// the immutable form a CloudEvent dataschema references.
func schemaVersionURL(doc *Export, xid string) (string, error) {
	gid, sid, ok := splitSchemaXID(xid)
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	g, ok := doc.SchemaGroups[gid]
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	s, ok := g.Schemas[sid]
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	for _, v := range s.Versions {
		if v.IsDefault {
			return v.XID, nil
		}
	}
	return "", &SchemaNotFoundError{XID: xid}
}

// splitSchemaXID parses /schemagroups/<gid>/schemas/<sid>.
func splitSchemaXID(xid string) (gid, sid string, ok bool) {
	rest, ok := strings.CutPrefix(xid, "/schemagroups/")
	if !ok {
		return "", "", false
	}
	gid, rest, ok := strings.Cut(rest, "/schemas/")
	if !ok || gid == "" || rest == "" {
		return "", "", false
	}
	return gid, rest, true
}

func slicesContain(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}

