				VersionID:        "1",
				IsDefault:        true,
				Envelope:         m.Envelope,
				EnvelopeMetadata: m.EnvelopeMetadata,
				DataSchemaFormat: m.DataSchemaFormat,
				DataSchemaXID:    m.DataSchemaXID,
				DataContentType:  m.DataContentType,
			}
		}
		return nil
	}
	var dflt *MessageVersion
	for i := range m.Versions {
		v := &m.Versions[i]
		if v.IsDefault {
			return v
		}
		if dflt == nil {
			dflt = v
		}
	}
	// Versions without isdefault markers: fall back to the first — the
	// single implicit version every message carries.
	return dflt
}

