	if !Has {
		t.Fatal("HasMessageBlocks should see the publishes block")
	}
	pub, err := ReadPublishesBlock(wiringEntry(values))
	if err != nil || pub.Message != "product-exported" {
		t.Fatalf("ReadPublishesBlock = %+v, %v", pub, err)
	}
