// Channel renders the entry's single first channel for the table row;
// JSON output carries the full list.
func (e MessageEntry) Channel() string {
	if len(e.Channels) == 0 {
		return "-"
	}
	return e.Channels[0]
}

// workspaceMessages indexes the publishes declarations under dir. Scan and
// parse warnings are non-fatal: a malformed sibling record must not hide
// the messages the rest of the workspace declares.
func workspaceMessages(dir string, stderr interface{ Fprintln(a ...any) (int, error) }) []MessageEntry {
	return workspaceMessagesWarn(dir, func(w error) {
		fmt.Fprintln(stderr, "warning:", w)
	})
}

func workspaceMessagesWarn(dir string, warnf func(error)) []MessageEntry {
	entries, warnings := template.ListScaffolds(dir)
	for _, w := range warnings {
		warnf(w)
	}
	seen := map[string]bool{}
	var out []MessageEntry
	for _, e := range entries {
		pub, err := template.ReadPublishesBlock(e)
		if err != nil || pub == nil {
			// Malformed block: skipped here, reported by assembly when it
			// actually blocks a run.
			continue
		}
		if seen[pub.Message] {
			continue
		}
		seen[pub.Message] = true
		out = append(out, MessageEntry{
			Message:  pub.Message,
			Source:   messageSourceWorkspace,
			Type:     pub.Message,
			Contract: pub.Contract,
			Path:     e.Path,
		})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Message < out[j].Message })
	return out
}

// registryMessages reads the registry export into entries, optionally
// narrowed to one group. The unconfigured-registry and unreachable-registry
// failures are the degradation contract: unconfigured is a usage error
// naming the config key, unreachable is a wrapped error front-loading the
// fetch that failed.
func registryMessages(ctx context.Context, registryURLFlag, group string) ([]MessageEntry, error) {
	url, err := resolveRegistryURL(registryURLFlag)
	if err != nil {
		return nil, err
	}
	client, err := xregistry.New(url, WithUserAgentOption())
	if err != nil {
		return nil, err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}

	// Stable group order: the JSON document must not depend on Go map
	// iteration.
	ids := make([]string, 0, len(doc.MessageGroups))
	for id := range doc.MessageGroups {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	var out []MessageEntry
	for _, gid := range ids {
		g := doc.MessageGroups[gid]
		if group != "" && gid != group {
			continue
		}
		channels := producerEndpoints(doc, gid)
		for _, mid := range sortedMessageIDs(g) {
			m := g.Messages[mid]
			def := m.defaultMessage()
			if def == nil {
				continue
			}
			e := MessageEntry{
				Message:  m.ID,
				Source:   messageSourceRegistry,
				Group:    gid,
				Type:     envelopeType(def),
				Envelope: def.Envelope,
				Channels: channels,
			}
			if def.DataSchemaXID != "" {
				e.DataSchema = def.DataSchemaXID
				e.DataSchemaName = schemaName(def.DataSchemaXID)
