func exitCode(err error) int {
	if err == nil {
		return 0
	}
	var ue *usageError
	if errors.As(err, &ue) {
		return 2
	}
	// Unknown commands surface from cobra's Find before any command in the
	// tree runs, so they fall back to message prefix detection.
	if isCobraUsageError(err) {
